	sb.WriteString("\tkylix.RegisterApprovalCheck(cross(cur), ApprovedForKylix) // optional\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func MoveForKylix(cur realm, from, to address, itemID string) error {\n")
	sb.WriteString("\t// cur.Previous().Address() is the offer's address that `from` approved.\n")
	sb.WriteString("\t// Use only an approval of this one item: the transfer clears it.\n")
	sb.WriteString("\tif a, _ := token.GetApproved(grc721.TokenID(itemID)); a != cur.Previous().Address() {\n")
	sb.WriteString("\t\treturn errors.New(\"approve this offer's address for the item itself\")\n")
	sb.WriteString("\t}\n")
	sb.WriteString("\treturn ledger.CallerTeller().TransferFrom(0, cur, from, to, grc721.TokenID(itemID))\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func OwnerForKylix(id kylix.ItemID) address {\n")
	sb.WriteString("\towner, _ := token.OwnerOf(grc721.TokenID(id))\n")
	sb.WriteString("\treturn owner\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func ApprovedForKylix(id kylix.ItemID, spender address) bool {\n")
	sb.WriteString("\tapproved, _ := token.GetApproved(grc721.TokenID(id))\n")
	sb.WriteString("\treturn approved != \"\" && approved == spender // not IsApprovedForAll\n")
	sb.WriteString("}\n")
	sb.WriteString("```\n\n")
	sb.WriteString("`OwnerForKylix` and `ApprovedForKylix` must not panic and should not store anything: return the empty address or false for an id you do not know. ")
	sb.WriteString("Kylix calls them when a ring with your item is settled, and on that offer's and ring's own pages; posting, cancelling and the home page never call a third-party collection. (Official collections, Kylix's own, are also checked at posting and on the home page.) ")
	sb.WriteString("For an already-deployed collection that cannot be changed, deploy a small adapter realm that calls `kylix.RegisterAdapter` and crosses into the target collection as `cur.Sub(\"k/\" + cur.Previous().Address().String())`.\n")
	return sb.String()
}

// pinnedTokens are listed first in the post page's token dropdowns, when
// registered: wrapped GNOT and GnoSwap's GNS. The demo tokens follow them.
var pinnedTokens = []string{"gno.land/r/gnoland/wugnot.wugnot", "gno.land/r/gnoswap/gns.GNS"}

// knownAssets lists the choices for the post page's dropdowns, at most
// maxFormAssetOpts tokens and maxFormAssetOpts collections. Anyone can
// register tokens and collections, so the useful ones come first and cannot
// be pushed out: tokens are wugnot, GNS, the demo realm's tokens, then the
// rest of grc20reg in key order; collections are the official ones, then
// the rest. Every key in selected that is registered is always included.
func knownAssets(selected ...string) (tokens []string, colls []string) {
	seenTok := map[string]bool{}
	addTok := func(key string) {
		if !seenTok[key] && tokenOf(key) != nil {
			seenTok[key] = true
			tokens = append(tokens, key)
		}
	}
	for _, k := range pinnedTokens {
		addTok(k)
	}
	reg := grc20reg.GetRegistry()
	if demo := demoRealmPath(); demo != "" && reg != nil {
		reg.Iterate(demo+".", demo+"/", func(key string, _ any) bool {
			if len(tokens) >= maxFormAssetOpts {
				return true
			}
			addTok(key)
			return false
		})
	}
	for _, k := range selected {
		addTok(k)
	}
	if reg != nil {
		reg.Iterate("", "", func(key string, _ any) bool {
			if len(tokens) >= maxFormAssetOpts {
				return true
			}
			addTok(key)
			return false
		})
	}

	seenColl := map[string]bool{}
	for _, k := range selected {
		if IsCollection(k) && IsOfficial(k) && !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	keys, _ := collectionKeys("", maxFormAssetOpts)
	for _, k := range keys {
		if len(colls) >= maxFormAssetOpts {
			break
		}
		if !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	for _, k := range selected {
		if IsCollection(k) && !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	return tokens, colls
}

func writeKindSelect(sb *strings.Builder, name, desc, selected string, required bool) {
	sb.WriteString(gnoSelectOpt(name, "fungible", desc, selected == "" || selected == "fungible", required))
	sb.WriteString(gnoSelectOpt(name, "item", "", selected == "item", false))
}

func writeAssetSelect(sb *strings.Builder, name, desc, selected string, tokens, colls []string, required bool) {
	first := true
	addOpt := func(key string) {
		d := ""
		req := false
		if first {
			d = desc
			req = required
			first = false
		}
		sb.WriteString(gnoSelectOpt(name, key, d, key == selected, req))
	}
	for _, k := range tokens {
		addOpt(k)
	}
	for _, k := range colls {
		addOpt(k)
	}
	if first {
		// No registered assets yet; fall back to a plain input.
		sb.WriteString(gnoInput(name, desc, selected, required, false))
	}
}

func resolveOwnerInput(raw string) (address, string) {
	s := strings.TrimSpace(raw)
	if s == "" {
		return "", ""
	}
	s = strings.TrimPrefix(s, "@")
	if a := address(s); a.IsValid() {
		return a, ""
	}
	if u, _ := users.ResolveName(s); u != nil {
		return u.Addr(), ""
	}
	return "", "Enter a valid g1 address or a registered username."
}

func parseKindChoice(s string) string {
	switch strings.TrimSpace(s) {
	case "fungible":
		return "fungible"
	case "item":
		return "item"
	}
	return ""
}

// allowAssetKey accepts a key only if it is a registered token or
// collection, by direct lookup: no list of choices can crowd it out.
func allowAssetKey(raw string) string {
	s := strings.TrimSpace(raw)
	if s == "" || len(s) > 256 {
		return ""
	}
	if IsCollection(s) || tokenOf(s) != nil {
		return s
	}
	return ""
}

func cleanItemIDInput(raw string) string {
	s := strings.TrimSpace(raw)
	if validItemID(s) {
		return s
	}
	return ""
}

func parseNonNegInt64(raw string) int64 {
	s := strings.TrimSpace(raw)
	if s == "" {
		return 0
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		return 0
	}
	return n
}

func formatIntOrEmpty(n int64) string {
	if n <= 0 {
		return ""
	}
	return strconv.FormatInt(n, 10)
}

func formatFeePercent(fee uint32) string {
	switch fee {
	case 100:
		return "0.01%"
	case 500:
		return "0.05%"
	case 3000:
		return "0.30%"
	case 10000:
		return "1.00%"
	}
	return strconv.FormatUint(uint64(fee), 10)
}

// plainSwapReason rewords internal p/ring error wording ("leg"/"legs") so
// user-facing pages speak consistently in terms of swaps and offers.
func plainSwapReason(s string) string {
	s = strings.ReplaceAll(s, " legs", " swaps")
	s = strings.ReplaceAll(s, "leg ", "swap ")
	return s
}

package kylix

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// SettleRing settles a ring of open offers. ids lists offer ids in ring
// order, comma-separated: the first offer's asset goes to the second offer's
// owner, and so on, and the last offer's asset goes to the first owner.
// Anyone may call it; the realm checks everything.
//
// A hop that gives one token where the receiver wants a different token is
// bridged by a GnoSwap swap (bridge.gno); a ring may contain one such hop.
// SettleRing picks the pool itself (see bridgeFee). That is a convenience:
// for a pair with several pools anyone can add liquidity that makes it pick
// a pool which cannot pay the receiver's minimum, and then the ring aborts.
// A settler who knows which pool to use calls SettleRingVia instead.
//
// Order of work:
//  1. Read and check: every offer is open and not expired, the ring is valid
//     (p/ring), every owner can deliver right now (balance and slot
//     allowance for a token; current ownership, and approval where the
//     collection registered a check, for an item), and a pool exists for a
//     bridged hop. This phase writes nothing to Kylix, and a failure names
//     the leg and offer at fault.
//  2. Take the re-entrancy lock and mark every offer settled by deleting it
//     from the book.
//  3. Move each leg's asset from its owner straight to the next owner, acting
//     as that offer's slot. After each item move, check that the next owner
//     really holds the item.
//
// If anything fails the transaction aborts and the chain rolls back every
// write, so the offers in the ring stay open and nothing has moved.
//
// SETTLERS PAY FOR COLLECTION CODE. For every item in the ring, phases 1 and
// 3 call that collection's registered functions. They run with their own
// realm's storage authority and may write to it, and the chain charges the
// transaction's sender the storage deposit for every realm whose storage
// grows. A hostile collection can therefore make settling its items cost up
// to the sender's deposit limit, and recover that deposit later. Settle with
// a tight -max-deposit, and be careful with third-party collections.
func SettleRing(cur realm, ids string) {
	settleRing(cur, ids, 0)
}

// SettleRingVia settles a ring like SettleRing, swapping its bridged hop
// through the GnoSwap pool with this fee tier (100, 500, 3000 or 10000,
// i.e. 0.01%, 0.05%, 0.3% or 1%). The pool must exist, and the ring must
// have a bridged hop. A solver chooses the pool off chain, for instance with
// the router's DrySwapRoute.
func SettleRingVia(cur realm, ids string, fee uint32) {
	if !isFeeTier(fee) {
		panic("kylix: fee must be one of GnoSwap's tiers: 100, 500, 3000 or 10000")
	}
	settleRing(cur, ids, fee)
}

// settleRing is SettleRing with an optional fee tier (0: choose).
func settleRing(cur realm, ids string, viaFee uint32) {
	guard(cur)
	idList, err := ring.ParseOfferIDs(ids)
	if err != nil {
		panic("kylix: " + err.Error())
	}

	height := runtime.ChainHeight()
	n := len(idList)
	offs := make([]*Offer, n)
	legs := make([]ring.Leg, n)
	for i, id := range idList {
		o := loadOffer(id)
		if o == nil {
			panic(legMsg(i, id, "offer is not open (unknown, settled, cancelled or pruned)"))
		}
		if expired(o, height) {
			panic(legMsg(i, id, "offer expired at height "+strconv.FormatInt(o.Expiry, 10)))
		}
		offs[i] = o
		legs[i] = ring.Leg{Offer: o.ID, Owner: o.Owner, Give: o.Give, Want: o.Want}
	}
	hops, err := ring.VerifyWithBridge(legs)
	if err != nil {
		panic("kylix: " + err.Error())
	}
	var fee uint32
	bridged := false
	for i, o := range offs {
		if why := undeliverable(o); why != "" {
			panic(legMsg(i, o.ID, why))
		}
		h := hops[i]
		if !h.Bridged {
			continue
		}
		bridged = true
		if viaFee != 0 {
			if !poolExists(h.Asset.Key, h.Want.Key, viaFee) {
				panic(legMsg(i, o.ID, "no GnoSwap pool with fee tier "+strconv.FormatUint(uint64(viaFee), 10)+
					" to swap "+h.Asset.Key+" for "+h.Want.Key))
			}
			fee = viaFee
			continue
		}
		var ok bool
		if fee, ok = bridgeFee(h.Asset.Key, h.Want.Key); !ok {
			panic(legMsg(i, o.ID, "no GnoSwap pool with reserves to swap "+h.Asset.Key+" for "+h.Want.Key))
		}
	}
	if viaFee != 0 && !bridged {
		panic("kylix: this ring has no swap through GnoSwap; use SettleRing")
	}

	locked = true
	for _, o := range offs {
		removeOffer(o.ID)
	}

	var bridgedGot int64
	for i, h := range hops {
		o := offs[i]
		slot := cur.Sub(slotPath(o.Owner, o.Nonce))
		to := offs[h.To].Owner
		if h.Bridged {
			settle := cur.Sub(settlePath)
			before := tokenOf(h.Want.Key).BalanceOf(to)
			bridgeHop(0, slot, settle, i, o, h, to, fee)
			bridgedGot = tokenOf(h.Want.Key).BalanceOf(to) - before
		} else {
			executeHop(0, slot, i, o, h, to)
		}
	}
	locked = false

	ringIDs := ring.FormatOfferIDs(idList)
	chain.Emit("RingSettled",
		"ids", ringIDs,
		"legs", strconv.Itoa(n),
		"settler", cur.Previous().Address().String(),
	)
	for i, o := range offs {
		in := (i + n - 1) % n
		received := hops[in].Asset.String()
		if hops[in].Bridged {
			received = ring.Asset{Kind: ring.Fungible, Key: hops[in].Want.Key, Amount: bridgedGot}.String()
		}
		chain.Emit(OfferSettledEvent,
			"owner", o.Owner.String(),
			"id", u64(o.ID),
			"ring", ringIDs,
			"gave", o.Give.String(),
			"received", received,
		)
	}
}

// executeHop moves one direct leg's asset. slot is the offer's own
// sub-realm token, minted from SettleRing's cur; it is never stored and
// never handed to foreign code except as the identity of a crossing call.
func executeHop(_ int, slot realm, i int, o *Offer, h ring.Hop, to address) {
	switch h.Asset.Kind {
	case ring.Fungible:
		// The slot is the spender, so only this offer's allowance can pay.
		grc20reg.TransferFrom(0, slot, h.Asset.Key, o.Owner, to, h.Asset.Amount)
	case ring.Item:
		c := getCollection(h.Asset.Key)
		if err := c.move(cross(slot), o.Owner, to, h.Asset.ID); err != nil {
			panic(legMsg(i, o.ID, "collection refused the move: "+err.Error()))
		}
		if got := c.ownerOf(ItemID(h.Asset.ID)); got != to {
			panic(legMsg(i, o.ID, "collection reported a move but item "+h.Asset.ID+" is owned by "+got.String()+", not "+to.String()))
		}
	default:
		panic(legMsg(i, o.ID, "unknown asset kind"))
	}
}

// undeliverable returns "" if o's owner could deliver o's asset right now,
// otherwise the reason not. It writes nothing to Kylix. For an item it calls
// the collection's OwnerFn and, if registered, its ApprovedFn; both run
// without crossing, so they cannot call back into Kylix's entry points, but
// they run with their own realm's storage authority and may write there, at
// the transaction sender's expense (see SettleRing). Without an ApprovedFn an
// item approval is only tested by the move itself.
func undeliverable(o *Offer) string {
	switch o.Give.Kind {
	case ring.Fungible:
		tok := tokenOf(o.Give.Key)
		if tok == nil {
			return "token is not in grc20reg"
		}
		need := o.Give.Amount
		if bal := tok.BalanceOf(o.Owner); bal < need {
			return "owner holds " + i64(bal) + " of " + o.Give.Key + ", offer gives " + i64(need)
		}
		// The allowance must equal the amount exactly. A larger one is not
		// used up, so the token realm keeps its entry and the settler, who
		// pays for every receiver's new balance entry, gets no refund for it.
		slot := SlotAddress(o.Owner, o.Nonce)
		if al := tok.Allowance(o.Owner, slot); al != need {
			return "slot " + slot.String() + " may spend " + i64(al) + " of " + o.Give.Key +
				"; approve exactly " + i64(need) + ", the amount this offer gives"
		}
	case ring.Item:
		c := getCollection(o.Give.Key)
		if c == nil {
			return "collection is not registered"
		}
		if got := c.ownerOf(ItemID(o.Give.ID)); got != o.Owner {
			return "owner no longer holds item " + o.Give.ID
		}
		if c.approved != nil {
			spender := ApproveTarget(o.Owner, o.Nonce, o.Give.Key)
			if !c.approved(ItemID(o.Give.ID), spender) {
				return "item " + o.Give.ID + " cannot be moved by " + spender.String() +
					" now (not approved, held by its collection, or refused by the collection's own rules)"
			}
		}
	default:
		return "unknown asset kind"
	}
	return ""
}

func tokenOf(key string) *grc20.Token { return grc20reg.Get(key) }

func legMsg(i int, id uint64, msg string) string {
	return "kylix: leg " + strconv.Itoa(i) + " (offer " + u64(id) + "): " + msg
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

package kylix

import (
	"strconv"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
)

// Storage layout.
//
// The chain charges the sender 100 ugnot per byte of realm storage, and a
// persisted struct costs far more than its contents: every object carries
// its own metadata and every field its type. An offer stored as an *Offer
// with two nested ring.Asset values in an avl.Tree took about 4.3 KB, or
// 0.43 GNOT, to post. So each open offer is stored as one string in a B+
// tree, and decoded into an Offer when read; that costs about 0.6-0.8 KB.
//
// The string is 12 fields joined by '|':
//
//	owner|nonce|giveKind|giveKey|giveID|giveAmount|wantKind|wantKey|wantID|wantMin|expiry|viaSession
//
// No field can contain '|': owners are bech32, keys are package paths or
// grc20reg keys, and item ids are validated by PostIntent. encodeOffer
// checks anyway.
var offers bptree.BPTree // offerKey(id) -> encoded offer, open offers only

const sep = "|"

func loadOffer(id uint64) *Offer {
	v := offers.Get(offerKey(id))
	if v == nil {
		return nil
	}
	return decodeOffer(id, v.(string))
}

func storeOffer(o *Offer) { offers.Set(offerKey(o.ID), encodeOffer(o)) }

// eachOfferAfter calls fn for every open offer with id > after, in id
// order, until fn returns true.
func eachOfferAfter(after uint64, fn func(o *Offer) bool) {
	if after == ^uint64(0) {
		return
	}
	start := ""
	if after > 0 {
		start = offerKey(after + 1)
	}
	offers.Iterate(start, "", func(k string, v any) bool { return fn(decodeOffer(parseOfferKey(k), v.(string))) })
}

// eachOfferBefore calls fn for every open offer with id < before (all when
// before is 0), newest first, until fn returns true.
func eachOfferBefore(before uint64, fn func(o *Offer) bool) {
	end := "" // ReverseIterate's end bound is inclusive
	switch {
	case before == 1:
		return
	case before > 1:
		end = offerKey(before - 1)
	}
	offers.ReverseIterate("", end, func(k string, v any) bool { return fn(decodeOffer(parseOfferKey(k), v.(string))) })
}

func encodeOffer(o *Offer) string {
	session := "0"
	if o.ViaSession {
		session = "1"
	}
	fields := []string{
		o.Owner.String(), u64(o.Nonce),
		kindDigit(o.Give.Kind), o.Give.Key, o.Give.ID, i64(o.Give.Amount),
		kindDigit(o.Want.Kind), o.Want.Key, o.Want.ID, i64(o.Want.Amount),
		i64(o.Expiry), session,
	}
	for _, f := range fields {
		if strings.Contains(f, sep) {
			panic("kylix: field contains the separator")
		}
	}
	return strings.Join(fields, sep)
}

// decodeOffer reverses encodeOffer in one pass. Pages decode every offer
// they show, so this is their main cost. In the GnoVM, ranging over a []byte
// costs about a quarter of indexing a string byte by byte, and far less than
// strings.Split followed by strconv parsing, so numbers are read as the scan
// passes them.
func decodeOffer(id uint64, s string) *Offer {
	var str [12]string // text fields
	var num [12]int64  // numeric fields
	field, start := 0, 0
	var n int64
	for i, c := range []byte(s) {
		if c == '|' {
			if field >= 11 {
				panic("kylix: corrupt offer record")
			}
			str[field], num[field] = s[start:i], n
			field, start, n = field+1, i+1, 0
		} else if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	if field != 11 {
		panic("kylix: corrupt offer record")
	}
	str[11], num[11] = s[start:], n
	// Numeric fields hold digits only (encodeOffer writes them with
	// strconv), so the running value above is exact for them.
	return &Offer{
		ID:         id,
		Owner:      address(str[0]),
		Nonce:      uint64(num[1]),
		Give:       ring.Asset{Kind: ring.Kind(num[2]), Key: str[3], ID: str[4], Amount: num[5]},
		Want:       ring.Asset{Kind: ring.Kind(num[6]), Key: str[7], ID: str[8], Amount: num[9]},
		Expiry:     num[10],
		ViaSession: str[11] == "1",
	}
}

// offerKey writes id in decimal behind a letter giving its length, so keys
// are short and still sort in numeric order: 7 -> "a7", 42 -> "b42".
func offerKey(id uint64) string {
	s := u64(id)
	return string(rune('a'+len(s)-1)) + s
}

func parseOfferKey(k string) uint64 { return mustU64(k[1:]) }

func kindDigit(k ring.Kind) string { return strconv.Itoa(int(k)) }

func mustU64(s string) uint64 {
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		panic("kylix: corrupt number in store")
	}
	return n
}

func mustI64(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("kylix: corrupt number in store")
	}
	return n
}

package kylix

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
	"gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/router"
	"gno.land/r/nt/grc20reg/v0"
)

// The GnoSwap bridge (decision 6). A ring may contain one hop that gives
// token A to someone who wants token B; Kylix swaps A for B on GnoSwap in
// the middle of the settlement. See docs/research/gnoswap-bridge.md.
//
// The input passes through Kylix's own sub-address cur.Sub("settle") for
// the length of one swap, because the router pays out to whoever called it.
// It is empty again before SettleRing returns.

const (
	// routerPath is the router proxy. The input allowance must be on this
	// address: the router pulls the input with its own RealmTeller.
	routerPath = "gno.land/r/gnoswap/router"
	settlePath = "settle"
)

var feeTiers = [4]uint32{100, 500, 3000, 10000}

// bridgeFee picks the fee tier SettleRing swaps through: among the pools
// that exist for the pair and hold some of the output token, the one holding
// the most of it. It returns false when there is none. It only reads (pool
// getters run without crossing and have no realm value with which to call
// back).
//
// A pool's balance counts liquidity at every price, so it is a poor guide
// when a pair has several pools: anyone can add liquidity that sits far from
// the current price and make this choose a pool that cannot pay the
// receiver's minimum, which aborts the ring. The receiver never gets less
// than their minimum either way. SettleRingVia lets the settler name the
// pool; this automatic choice is a convenience for pairs with one pool.
//
// No price quote is taken here: a DrySwapRoute costs about 20M gas.
func bridgeFee(keyIn, keyOut string) (uint32, bool) {
	best, found := uint32(0), false
	var bestReserve int64
	outIsToken1 := strings.Compare(keyOut, keyIn) > 0
	for _, fee := range feeTiers {
		path := pool.GetPoolPath(keyIn, keyOut, fee)
		if !pool.ExistsPoolPath(path) {
			continue
		}
		b0, b1, err := pool.GetBalances(path)
		if err != nil {
			continue
		}
		reserve := b0
		if outIsToken1 {
			reserve = b1
		}
		if reserve > bestReserve {
			best, bestReserve, found = fee, reserve, true
		}
	}
	return best, found
}

// poolExists reports whether a GnoSwap pool exists for the pair at fee.
func poolExists(keyIn, keyOut string, fee uint32) bool {
	return pool.ExistsPoolPath(pool.GetPoolPath(keyIn, keyOut, fee))
}

// isFeeTier reports whether fee is one of GnoSwap's fee tiers.
func isFeeTier(fee uint32) bool {
	for _, f := range feeTiers {
		if f == fee {
			return true
		}
	}
	return false
}

// bridgeHop settles a bridged hop: pull the offer's input through its slot
// into the settle sub-address, swap it as that sub-address, check that the
// whole input was used and that the output meets the receiver's minimum,
// and forward all of the output to the receiver. slot and settle are
// sub-realm tokens minted from SettleRing's cur; this is called without
// crossing so both stay current.
func bridgeHop(_ int, slot, settle realm, i int, o *Offer, h ring.Hop, to address, fee uint32) {
	keyIn, keyOut := h.Asset.Key, h.Want.Key
	amountIn, wantMin := h.Asset.Amount, h.Want.Amount
	settleAddr := settle.Address()
	routerAddr := chain.PackageAddress(routerPath)
	route := keyIn + ":" + keyOut + ":" + strconv.FormatUint(uint64(fee), 10)

	grc20reg.TransferFrom(0, slot, keyIn, o.Owner, settleAddr, amountIn)
	grc20reg.Approve(0, settle, keyIn, routerAddr, amountIn)
	usedStr, gotStr := router.ExactInSingleSwapRoute(cross(settle),
		keyIn, keyOut, i64(amountIn), route, i64(wantMin), "0", time.Now().Unix(), "")

	used, err := strconv.ParseInt(usedStr, 10, 64)
	if err != nil || used != amountIn {
		panic(legMsg(i, o.ID, "swap used "+usedStr+" of "+i64(amountIn)+"; a leg gives its whole amount"))
	}
	// The router spent exactly the allowance, which deletes it. Setting it to
	// 0 again would store a zero entry, so check instead of resetting.
	if left := tokenOf(keyIn).Allowance(settleAddr, routerAddr); left != 0 {
		panic(legMsg(i, o.ID, "router allowance left after the swap: "+i64(left)))
	}
	got, err := strconv.ParseInt(gotStr, 10, 64)
	if err != nil || got <= 0 || got < wantMin {
		panic(legMsg(i, o.ID, "swap returned "+gotStr+" of "+keyOut+", receiver wants at least "+i64(wantMin)))
	}
	grc20reg.Transfer(0, settle, keyOut, to, got)
}

// SettleAddress is the sub-address a bridged swap passes through. It holds
// nothing between transactions.
func SettleAddress() address { return chain.DerivePkgSubAddr(selfPath, settlePath) }

package kylix

import (
	"chain"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
)

// ItemID names an item when Kylix asks a collection about it.
//
// It is declared here, not as a plain string, so that only realm code can
// implement OwnerFn or ApprovedFn: a /p/ package cannot import this realm,
// so it cannot name this type. That closes the one gap a non-crossing
// callback would otherwise leave open (a top-level /p/ function called from
// here would run with this realm's storage authority; see
// gno-security-guide.md section 3C).
type ItemID string

// MoveFn moves one item from `from` to `to`. Kylix calls it crossing, as the
// offer's slot sub-address: inside it, cur.Previous().Address() is the slot
// that `from` approved for that one offer. It must move the item only if
// that address is approved for it, and return an error (or panic) otherwise.
// Because it is a crossing function, it can only be declared in a realm.
//
// An adapter's MoveFn instead crosses into its target collection as its own
// sub-identity "k/<slot address>" (see RegisterAdapter).
type MoveFn func(cur realm, from, to address, itemID string) error

// OwnerFn reports who owns an item, or the empty address if nobody does.
// Kylix calls it without crossing, so it runs with its collection's storage
// and has no realm value with which to call back into Kylix.
type OwnerFn func(itemID ItemID) address

// ApprovedFn reports whether spender may move the item now. It is optional
// (see RegisterApprovalCheck); like OwnerFn it is called without crossing.
type ApprovedFn func(itemID ItemID, spender address) bool

type collection struct {
	name     string
	move     MoveFn
	ownerOf  OwnerFn
	approved ApprovedFn // optional
	target   string     // adapters only: the collection realm the adapter drives
}

// Collection describes a registered collection. All strings are untrusted
// text; escape them before rendering.
type Collection struct {
	Key           string // the registering realm's package path
	Name          string
	Adapter       bool   // registered with RegisterAdapter
	Target        string // adapters only: the collection realm it drives
	Official      bool   // the key is under Kylix's own namespace
	Label         string // "official collection", "official adapter", "third-party collection" or "third-party adapter"
	ApprovalCheck bool   // an ApprovedFn is registered
}

const (
	maxCollectionNameLen = 64
	maxTargetLen         = 200
	adapterSubPrefix     = "k/"
)

var collections avl.Tree // realm pkgpath -> *collection

// RegisterItem registers the calling realm as a collection whose items can
// be traded. The collection key is the caller's package path, so no realm can
// register under another's name, and a realm registers once: what Kylix
// calls for its items never changes after offers have been posted.
//
// Kylix trusts a collection only about its own items. After every move it
// checks ownerOf(id) == to, so a collection that says it moved an item it
// did not can only hurt people who chose to want that collection's items.
func RegisterItem(cur realm, name string, move MoveFn, ownerOf OwnerFn) {
	guard(cur)
	register(0, cur.Previous(), name, "", move, ownerOf)
}

// RegisterAdapter registers the calling realm as an adapter for an existing
// collection realm, target, that knows nothing of Kylix. The key is still
// the adapter's own package path; target is recorded for display.
//
// The difference is the address an owner approves in the target collection:
// not the offer's slot but the adapter's sub-address
// DerivePkgSubAddr(adapterPath, "k/"+slotAddress), which ApproveTarget
// returns. The adapter's MoveFn crosses into the target as
// cur.Sub("k/"+cur.Previous().Address()), so only that one slot can ever
// produce the identity the owner approved.
//
// An adapter whose path sits under Kylix's own namespace is labelled
// official, any other third-party. The label is information only; nothing
// is blocked on it.
func RegisterAdapter(cur realm, target, name string, move MoveFn, ownerOf OwnerFn) {
	guard(cur)
	if !validTarget(target) {
		panic("kylix: target must be the package path of a realm, e.g. gno.land/r/owner/collection")
	}
	prev := cur.Previous()
	if target == prev.PkgPath() {
		panic("kylix: an adapter cannot target itself; use RegisterItem")
	}
	register(0, prev, name, target, move, ownerOf)
}

// RegisterApprovalCheck adds an ApprovedFn to the calling realm's
// registration, once. SettleRing then refuses, before anything moves and
// naming the leg, an item that is not approved for ApproveTarget(...).
func RegisterApprovalCheck(cur realm, approved ApprovedFn) {
	guard(cur)
	c := getCollection(cur.Previous().PkgPath())
	if c == nil {
		panic("kylix: register the collection first")
	}
	if approved == nil {
		panic("kylix: approved is required")
	}
	if c.approved != nil {
		panic("kylix: approval check already registered")
	}
	c.approved = approved
	chain.Emit("ApprovalCheckRegistered", "key", cur.Previous().PkgPath())
}

func register(_ int, prev realm, name, target string, move MoveFn, ownerOf OwnerFn) {
	key := prev.PkgPath()
	if key == "" {
		panic("kylix: only a realm can register a collection")
	}
	if prev.IsEphemeral() {
		panic("kylix: a MsgRun package cannot register a collection")
	}
	if strings.Contains(key, "#") {
		panic("kylix: register from the realm itself, not from a sub-identity")
	}
	if move == nil || ownerOf == nil {
		panic("kylix: move and ownerOf are both required")
	}
	if !validName(name) {
		panic("kylix: collection name must be 1-64 bytes of printable UTF-8")
	}
	if collections.Has(key) {
		panic("kylix: collection already registered")
	}
	collections.Set(key, &collection{name: name, move: move, ownerOf: ownerOf, target: target})
	chain.Emit("CollectionRegistered", "key", key, "name", name, "target", target)
}

// ApproveTarget returns the exact address an owner must approve for the
// offer with this owner and nonce that gives an asset under key: the slot
// for a token or a native collection, the adapter's derived sub-address for
// an adapter. It reads only Kylix's own state.
func ApproveTarget(owner address, nonce uint64, key string) address {
	slot := SlotAddress(owner, nonce)
	if c := getCollection(key); c != nil && c.target != "" {
		return chain.DerivePkgSubAddr(key, adapterSubPrefix+slot.String())
	}
	return slot
}

// IsCollection reports whether key is a registered collection.
func IsCollection(key string) bool { return collections.Has(key) }

// CollectionName returns the display name a collection registered with.
// It is untrusted text; escape it before rendering.
func CollectionName(key string) string {
	c := getCollection(key)
	if c == nil {
		return ""
	}
	return c.name
}

// GetCollection describes a registered collection.
func GetCollection(key string) (Collection, bool) {
	c := getCollection(key)
	if c == nil {
		return Collection{}, false
	}
	return describe(key, c), true
}

// IsOfficial reports whether key sits under Kylix's own namespace, e.g.
// gno.land/r/<namespace>/... for Kylix at gno.land/r/<namespace>/kylix.
func IsOfficial(key string) bool {
	ns := namespacePrefix()
	return ns != "" && strings.HasPrefix(key, ns)
}

func describe(key string, c *collection) Collection {
	return Collection{
		Key:           key,
		Name:          c.name,
		Adapter:       c.target != "",
		Target:        c.target,
		Official:      IsOfficial(key),
		Label:         collectionKind(key),
		ApprovalCheck: c.approved != nil,
	}
}

// namespacePrefix is the first three segments of Kylix's own path plus a
// slash, e.g. "gno.land/r/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/".
func namespacePrefix() string {
	parts := strings.SplitN(selfPath, "/", 4)
	if len(parts) < 3 {
		return ""
	}
	return parts[0] + "/" + parts[1] + "/" + parts[2] + "/"
}

func getCollection(key string) *collection {
	v := collections.Get(key)
	if v == nil {
		return nil
	}
	return v.(*collection)
}

func validName(s string) bool {
	if len(s) == 0 || len(s) > maxCollectionNameLen || !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		switch {
		case r < 0x20, r == 0x7f, r >= 0x80 && r < 0xa0: // control characters
			return false
		case r >= 0x200b && r <= 0x200f, r >= 0x2028 && r <= 0x202e, r >= 0x2066 && r <= 0x2069, r == 0xfeff:
			return false // zero-width, line separators and bidi overrides
		}
	}
	return true
}

// validTarget accepts a realm package path: <domain>/r/<rest>, lowercase
// letters, digits and . _ - / only.
func validTarget(s string) bool {
	if len(s) == 0 || len(s) > maxTargetLen || !strings.Contains(s, "/r/") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '.', c == '_', c == '-', c == '/':
		default:
			return false
		}
	}
	return !strings.Contains(s, "//") && !strings.HasSuffix(s, "/")
}

package kylix

import (
	"chain/runtime"
	"strconv"
	"strings"
)

// MaxDeliverableBatch bounds one Deliverable query. A token offer costs two
// ledger reads; an item offer calls its collection's OwnerFn and, if
// registered, ApprovedFn, which is foreign code of unknown cost.
const MaxDeliverableBatch = 50

// Deliverable reports, for each of up to MaxDeliverableBatch comma-separated
// offer ids, whether its owner could deliver it right now and, if not, why.
// It runs the same check as SettleRing's preflight, so a
// solver can screen candidates in one query instead of one or two per offer:
//
//	{"height":123,"offers":[
//	  {"id":7,"deliverable":true,"reason":""},
//	  {"id":9,"deliverable":false,"reason":"slot g1... may spend 0 of ..., offer gives 10"},
//	  {"id":12,"deliverable":false,"reason":"not open"}]}
//
// An expired offer is reported as not deliverable with reason "expired".
// It writes nothing to Kylix, but for an item it calls the collection's
// registered functions, which may write to their own realm's storage (see
// SettleRing); as a query that costs nothing. Bridged hops need a pool too;
// that is not checked here.
func Deliverable(ids string) string {
	assertNotSettling()
	parts := strings.Split(ids, ",")
	if strings.TrimSpace(ids) == "" || len(parts) > MaxDeliverableBatch {
		panic("kylix: Deliverable takes 1 to " + strconv.Itoa(MaxDeliverableBatch) + " offer ids")
	}
	h := runtime.ChainHeight()
	var sb strings.Builder
	sb.WriteString(`{"height":`)
	sb.WriteString(strconv.FormatInt(h, 10))
	sb.WriteString(`,"offers":[`)
	for i, p := range parts {
		id, err := strconv.ParseUint(strings.TrimSpace(p), 10, 64)
		if err != nil || id == 0 {
			panic("kylix: bad offer id " + strconv.Quote(strings.TrimSpace(p)))
		}
		reason := "not open"
		if o := loadOffer(id); o != nil {
			if expired(o, h) {
				reason = "expired"
			} else {
				reason = undeliverable(o)
			}
		}
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(`{"id":`)
		sb.WriteString(u64(id))
		sb.WriteString(`,"deliverable":`)
		sb.WriteString(strconv.FormatBool(reason == ""))
		sb.WriteString(`,"reason":`)
		sb.WriteString(jsonString(reason))
		sb.WriteByte('}')
	}
	sb.WriteString(`]}`)
	return sb.String()
}

package kylix

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
)

const (
	// DefaultExportPage and MaxExportPage bound ExportGraphJSONPage, so one
	// query stays within the read-gas limit however large the book grows.
	DefaultExportPage = 100
	MaxExportPage     = 500
)

// ExportGraphJSON returns every open, unexpired offer and every registered
// collection as JSON, for off-chain solvers looking for rings. Its cost
// grows with the book; past a few hundred offers use ExportGraphJSONPage.
//
//	{"realm":"gno.land/r/...","height":123,
//	 "collections":[{"key":"gno.land/r/...","name":"...","adapter":false,
//	   "target":"","official":true,"approvalCheck":true}],
//	 "offers":[{"id":1,"owner":"g1...","nonce":1,"slot":"g1...","approve":"g1...",
//	   "give":{"kind":"fungible","key":"gno.land/r/x.FOO","id":"","amount":"100"},
//	   "want":{"kind":"item","key":"gno.land/r/y","id":"relic-7","amount":"0"},
//	   "expiry":12345,"viaSession":false}],
//	 "hasMore":false,"next":0,"total":1}
//
// Amounts are decimal strings because int64 does not fit a JSON number in
// most parsers. "approve" is the address the owner must have approved (see
// ApproveTarget); a solver can check it before proposing a ring, or ask
// Deliverable. Offers are in id order. "hasMore" says another page follows
// and "next" is the cursor to pass as `after` for it (0 when hasMore is
// false). "total" counts every open offer in the book, expired ones
// included until pruned, so it can exceed what the pages list.
func ExportGraphJSON() string {
	assertNotSettling()
	return exportJSON(0, -1)
}

// ExportGraphJSONPage returns at most limit open, unexpired offers with id
// greater than after (limit <= 0 means DefaultExportPage; at most
// MaxExportPage). It looks at no more than MaxExportPage offers, expired
// ones included, so its cost is bounded however many offers have expired;
// a page can therefore hold fewer than limit offers and still have
// "hasMore" set. "collections" is included only in the first page (after
// == 0). Page with "hasMore" and "next" as ExportGraphJSON describes.
func ExportGraphJSONPage(after uint64, limit int) string {
	assertNotSettling()
	if limit <= 0 {
		limit = DefaultExportPage
	}
	if limit > MaxExportPage {
		limit = MaxExportPage
	}
	return exportJSON(after, limit)
}

// exportJSON lists offers after the given id; limit < 0 means all, with no
// scan bound.
func exportJSON(after uint64, limit int) string {
	h := runtime.ChainHeight()
	var sb strings.Builder
	sb.WriteString(`{"realm":`)
	sb.WriteString(jsonString(selfPath))
	sb.WriteString(`,"height":`)
	sb.WriteString(strconv.FormatInt(h, 10))
	if after == 0 {
		writeCollectionsJSON(&sb, "", MaxExportCollections)
	}
	sb.WriteString(`,"offers":[`)
	paged := limit >= 0
	count, scanned := 0, 0
	var last, next uint64 // last: id of the last offer looked at
	eachOfferAfter(after, func(o *Offer) bool {
		if paged && scanned == MaxExportPage {
			next = last // scan bound reached; more offers may remain
			return true
		}
		scanned++
		if expired(o, h) {
			last = o.ID
			return false
		}
		if paged && count == limit {
			next = last // an unexpired offer remains; resume after the last one seen
			return true
		}
		last = o.ID
		if count > 0 {
			sb.WriteByte(',')
		}
		writeOfferJSON(&sb, o)
		count++
		return false
	})
	sb.WriteString(`],"hasMore":`)
	sb.WriteString(strconv.FormatBool(next != 0))
	sb.WriteString(`,"next":`)
	sb.WriteString(u64(next))
	sb.WriteString(`,"total":`)
	sb.WriteString(strconv.Itoa(offers.Size()))
	sb.WriteString(`}`)
	return sb.String()
}

func writeOfferJSON(sb *strings.Builder, o *Offer) {
	sb.WriteString(`{"id":`)
	sb.WriteString(u64(o.ID))
	sb.WriteString(`,"owner":`)
	sb.WriteString(jsonString(o.Owner.String()))
	sb.WriteString(`,"nonce":`)
	sb.WriteString(u64(o.Nonce))
	sb.WriteString(`,"slot":`)
	sb.WriteString(jsonString(SlotAddress(o.Owner, o.Nonce).String()))
	sb.WriteString(`,"approve":`)
	sb.WriteString(jsonString(ApproveTarget(o.Owner, o.Nonce, o.Give.Key).String()))
	sb.WriteString(`,"give":`)
	writeAssetJSON(sb, o.Give)
	sb.WriteString(`,"want":`)
	writeAssetJSON(sb, o.Want)
	sb.WriteString(`,"expiry":`)
	sb.WriteString(strconv.FormatInt(o.Expiry, 10))
	sb.WriteString(`,"viaSession":`)
	sb.WriteString(strconv.FormatBool(o.ViaSession))
	sb.WriteByte('}')
}

// MaxExportCollections bounds the collections listed in one export: the
// first offers page carries up to this many, official ones first, and
// ExportCollectionsJSON pages through the rest.
const MaxExportCollections = 100

// ExportCollectionsJSON lists up to limit registered collections (at most
// MaxExportCollections; 0 for that maximum), official ones first, starting
// after the key after ("" for the start):
//
//	{"collections":[...],"collectionsHasMore":true,"collectionsNext":"gno.land/r/..."}
//
// Pass collectionsNext as after for the next page.
func ExportCollectionsJSON(after string, limit int) string {
	assertNotSettling()
	if limit <= 0 || limit > MaxExportCollections {
		limit = MaxExportCollections
	}
	var sb strings.Builder
	writeCollectionsJSON(&sb, after, limit)
	return "{" + strings.TrimPrefix(sb.String(), ",") + "}"
}

// writeCollectionsJSON writes `,"collections":[...],"collectionsHasMore":b,
// "collectionsNext":"key"`.
func writeCollectionsJSON(sb *strings.Builder, after string, limit int) {
	keys, more := collectionKeys(after, limit)
	sb.WriteString(`,"collections":[`)
	for i, key := range keys {
		if i > 0 {
			sb.WriteByte(',')
		}
		writeCollectionJSON(sb, describe(key, getCollection(key)))
	}
	sb.WriteString(`],"collectionsHasMore":`)
	sb.WriteString(strconv.FormatBool(more))
	next := ""
	if more {
		next = keys[len(keys)-1]
	}
	sb.WriteString(`,"collectionsNext":`)
	sb.WriteString(jsonString(next))
}

func writeCollectionJSON(sb *strings.Builder, c Collection) {
	sb.WriteString(`{"key":`)
	sb.WriteString(jsonString(c.Key))
	sb.WriteString(`,"name":`)
	sb.WriteString(jsonString(c.Name))
	sb.WriteString(`,"adapter":`)
	sb.WriteString(strconv.FormatBool(c.Adapter))
	sb.WriteString(`,"target":`)
	sb.WriteString(jsonString(c.Target))
	sb.WriteString(`,"official":`)
	sb.WriteString(strconv.FormatBool(c.Official))
	sb.WriteString(`,"label":`)
	sb.WriteString(jsonString(c.Label))
	sb.WriteString(`,"approvalCheck":`)
	sb.WriteString(strconv.FormatBool(c.ApprovalCheck))
	sb.WriteByte('}')
}

func writeAssetJSON(sb *strings.Builder, a ring.Asset) {
	sb.WriteString(`{"kind":`)
	sb.WriteString(jsonString(a.Kind.String()))
	sb.WriteString(`,"key":`)
	sb.WriteString(jsonString(a.Key))
	sb.WriteString(`,"id":`)
	sb.WriteString(jsonString(a.ID))
	sb.WriteString(`,"amount":"`)
	sb.WriteString(strconv.FormatInt(a.Amount, 10))
	sb.WriteString(`"}`)
}

// jsonString quotes s as a JSON string. Besides what JSON requires, it
// escapes <, >, & and U+2028/U+2029 so the output is also safe to embed in
// HTML or a JavaScript literal. Invalid UTF-8 becomes U+FFFD.
func jsonString(s string) string {
	const hex = "0123456789abcdef"
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\r':
			sb.WriteString(`\r`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r < 0x20, r == '<', r == '>', r == '&', r == 0x2028, r == 0x2029:
			sb.WriteString(`\u`)
			sb.WriteByte(hex[(r>>12)&0xf])
			sb.WriteByte(hex[(r>>8)&0xf])
			sb.WriteByte(hex[(r>>4)&0xf])
			sb.WriteByte(hex[r&0xf])
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// Package kylix settles trades in a circle. Each person posts an offer, "I
// give X, I want at least Y". When two to six offers form a closed ring,
// anyone can submit the ring and every leg settles in one transaction, or
// nothing moves.
//
// Kylix never holds anyone's assets. Before posting, an owner approves a
// sub-address of this realm that belongs to that one offer (see NextSlot).
// At settlement Kylix acts as that sub-address to move the offer's asset from
// its owner straight to the next owner in the ring.
package kylix

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
)

// Offer is one open offer, as decoded from storage (see store.gno). Every
// Offer value is a fresh copy, so nothing outside can alias state.
//
// There is no status field: only open offers are stored. Settling,
// cancelling or pruning an offer deletes it (releasing its storage deposit to
// whoever sent that transaction), and the event emitted says which.
type Offer struct {
	ID    uint64
	Owner address
	Nonce uint64 // per owner; the offer's slot is w/<owner>/<nonce>
	Give  ring.Asset
	Want  ring.Asset
	// Expiry is the last block height at which the offer may settle. Every
	// offer has one (see PostIntent); after it anyone may prune the offer.
	Expiry     int64
	ViaSession bool // posted by a session key
}

const (
	// BlocksPerDay assumes 5 s blocks.
	BlocksPerDay = 17280
	// DefaultExpiryBlocks is the lifetime of an offer posted with expiry 0:
	// about 7 days.
	DefaultExpiryBlocks = 7 * BlocksPerDay
	// MaxExpiryBlocks is the longest lifetime an offer may ask for: about 30
	// days. Every offer expires, so every offer can eventually be pruned.
	MaxExpiryBlocks = 30 * BlocksPerDay

	maxItemIDLen = 64
)

var (
	selfPath string        // this realm's package path, captured in init
	nonces   bptree.BPTree // owner -> uint64, last nonce used by that owner
	lastID   uint64

	// locked is true while SettleRing is moving assets. Every exported
	// function except Render refuses to run while it is set, so foreign code
	// called during a settlement can neither re-enter nor observe the book
	// half settled. A failed transaction rolls it back with everything else.
	locked bool

	// sessionCheck reports whether the transaction was signed by a session
	// key. It is a variable only so that in-package tests can simulate a
	// session signer, which `gno test` cannot produce. Nothing in this
	// package assigns it outside tests.
	sessionCheck = func() bool {
		_, _, _, isSession := runtime.GetSessionInfo()
		return isSession
	}
)

func init(cur realm) {
	selfPath = cur.PkgPath()
}

// NextSlot returns the nonce and the slot address that owner's next offer
// will use. The owner approves the slot for the offered asset, then calls
// PostIntent; both can go in one transaction because the slot is
// deterministic and only the owner can advance their own nonce.
func NextSlot(owner address) (nonce uint64, slot address) {
	if !owner.IsValid() {
		panic("kylix: invalid owner address")
	}
	nonce = lastNonce(owner) + 1
	return nonce, SlotAddress(owner, nonce)
}

// SlotAddress is the sub-address that may move the asset of owner's offer
// with the given nonce. Off chain: chain.DerivePkgSubAddr(<kylix path>,
// "w/<owner>/<nonce>").
func SlotAddress(owner address, nonce uint64) address {
	return chain.DerivePkgSubAddr(selfPath, slotPath(owner, nonce))
}

// PostIntent records an offer: the caller gives giveAmount of a token, or
// one item, and wants at least wantMin of a token, or one item. Kinds are
// "fungible" (key: a grc20reg key, id: empty) and "item" (key: a registered
// collection, id: the item id, amount: 0). expiry is the last block height
// at which the offer may settle: 0 means DefaultExpiryBlocks from now, and it
// may be at most MaxExpiryBlocks from now. It returns the offer id; the
// IntentPosted event carries the expiry it got.
//
// A token offer, or an item offer of an official collection, must be
// deliverable when it is posted: the same check settlement runs first (see
// undeliverable). For a token, the owner holds the amount and has approved
// NextSlot's address for exactly that amount; for an official item, the
// collection says the owner holds it and, if it registered an approval
// check, that ApproveTarget's address may move it. So approve first, then
// post (two messages in one transaction work). Nothing is pulled.
//
// An official collection's functions are Kylix's own code; Kylix holds its
// lock while they run, so they cannot post, cancel or settle, nor read the
// book. An item of a third-party collection is not checked: posting runs no
// third-party code, so a collection cannot bill the poster for storage
// (security review 4, R4-1). Such offers are kept off the home page and are
// checked when someone settles them.
func PostIntent(cur realm, giveKind, giveKey, giveID string, giveAmount int64, wantKind, wantKey, wantID string, wantMin int64, expiry int64) uint64 {
	guard(cur)
	owner := cur.Previous().Address()
	give := mustAsset("give", giveKind, giveKey, giveID, giveAmount)
	want := mustAsset("want", wantKind, wantKey, wantID, wantMin)
	if give.SameAs(want) {
		panic("kylix: an offer cannot give the asset it wants")
	}
	expiry = offerExpiry(expiry, runtime.ChainHeight())

	nonce := lastNonce(owner) + 1
	o := &Offer{
		ID:         lastID + 1,
		Owner:      owner,
		Nonce:      nonce,
		Give:       give,
		Want:       want,
		Expiry:     expiry,
		ViaSession: sessionCheck(),
	}
	why := ""
	if give.Kind == ring.Fungible || IsOfficial(give.Key) {
		locked = true
		why = undeliverable(o)
		locked = false
	}
	if why != "" {
		panic("kylix: give: the offer could not settle now (" + why + "); approve first, then post")
	}
	nonces.Set(owner.String(), nonce)
	lastID++
	storeOffer(o)

	chain.Emit("IntentPosted",
		"id", u64(o.ID),
		"owner", owner.String(),
		"slot", SlotAddress(owner, nonce).String(),
		"give", give.String(),
		"want", want.String(),
		"expiry", strconv.FormatInt(expiry, 10),
	)
	return o.ID
}

// CancelIntent withdraws an open offer. Only its owner may cancel, and not
// through a session key. It calls no foreign code, so nothing can stop an
// owner from cancelling. Cancelling does not revoke the owner's approval of
// the slot; the slot is never used again, but the owner may revoke it at the
// token or collection for tidiness.
func CancelIntent(cur realm, id uint64) {
	guard(cur)
	if sessionCheck() {
		panic("kylix: a session key cannot cancel an offer; sign with the account key")
	}
	o := mustOpen(id)
	if cur.Previous().Address() != o.Owner {
		panic("kylix: only the owner can cancel offer " + u64(id))
	}
	removeOffer(o.ID)
	chain.Emit("IntentCancelled", "id", u64(id), "owner", o.Owner.String())
}

// GetOffer returns an open offer, expired ones included until pruned.
func GetOffer(id uint64) (Offer, bool) {
	assertNotSettling()
	o := loadOffer(id)
	if o == nil {
		return Offer{}, false
	}
	return *o, true
}

// OpenOffers is the number of open offers, expired ones included until they
// are pruned.
func OpenOffers() int {
	assertNotSettling()
	return offers.Size()
}

// guard runs first in every state-changing entry point.
func guard(cur realm) {
	if locked {
		panic("kylix: re-entrant call during settlement")
	}
	// Kylix cannot send coins anywhere, so coins a user sends straight to it
	// would be stuck. Coins attached to a MsgRun or sent to a realm that then
	// calls Kylix went to that caller, not to Kylix, so they are not refused.
	// OriginSend is read only to refuse, never as proof of payment.
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("kylix: do not send coins; trade GNOT as wugnot")
	}
}

// assertNotSettling runs first in every exported read except Render: while
// SettleRing is moving assets the book is already updated but the assets
// are not, so a collection's callback must not be shown that state.
func assertNotSettling() {
	if locked {
		panic("kylix: settlement in progress")
	}
}

// offerExpiry turns PostIntent's expiry argument into a height: 0 means the
// default, a past or current height and one beyond the maximum are refused.
func offerExpiry(expiry, h int64) int64 {
	switch {
	case expiry == 0:
		return h + DefaultExpiryBlocks
	case expiry <= h:
		panic("kylix: expiry must be a future block height, or 0 for the default of " +
			strconv.Itoa(DefaultExpiryBlocks/BlocksPerDay) + " days")
	case expiry > h+MaxExpiryBlocks:
		panic("kylix: expiry may be at most " + strconv.Itoa(MaxExpiryBlocks/BlocksPerDay) +
			" days ahead, height " + strconv.FormatInt(h+MaxExpiryBlocks, 10))
	}
	return expiry
}

func mustOpen(id uint64) *Offer {
	o := loadOffer(id)
	if o == nil {
		panic("kylix: offer " + u64(id) + " is not open (unknown, settled, cancelled or pruned)")
	}
	return o
}

func removeOffer(id uint64) { offers.Remove(offerKey(id)) }

func expired(o *Offer, height int64) bool { return height > o.Expiry }

// mustAsset parses and validates one side of an offer against what is
// registered right now.
func mustAsset(side, kind, key, id string, amount int64) ring.Asset {
	k, ok := ring.ParseKind(kind)
	if !ok {
		panic("kylix: " + side + " kind must be \"fungible\" or \"item\"")
	}
	a := ring.Asset{Kind: k, Key: key, ID: id, Amount: amount}
	if r := a.Validate(); r != "" {
		panic("kylix: " + side + ": " + r)
	}
	switch k {
	case ring.Fungible:
		if tokenOf(key) == nil {
			panic("kylix: " + side + ": token is not in grc20reg")
		}
	case ring.Item:
		if getCollection(key) == nil {
			panic("kylix: " + side + ": collection is not registered with kylix")
		}
		if !validItemID(id) {
			panic("kylix: " + side + ": item id must be 1-64 characters of A-Z a-z 0-9 . _ : / - *")
		}
	}
	return a
}

func validItemID(id string) bool {
	if len(id) == 0 || len(id) > maxItemIDLen {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == '.', c == '_', c == ':', c == '/', c == '-', c == '*':
		default:
			return false
		}
	}
	return true
}

func lastNonce(owner address) uint64 {
	v := nonces.Get(owner.String())
	if v == nil {
		return 0
	}
	return v.(uint64)
}

func slotPath(owner address, nonce uint64) string {
	return "w/" + owner.String() + "/" + u64(nonce)
}

func u64(n uint64) string { return strconv.FormatUint(n, 10) }

package kylix

import (
	"chain/runtime"

	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
)

// Bounds for the on-page ring search. Every cap is constant so Render("")
// stays O(1) in book size even when thousands of offers are open or expired.
//
// What may take part (security review 3, R3-2). Every offer was deliverable
// when it was posted, but its owner can make it dead later by moving the
// asset or revoking the approval. So the search checks each offer again:
//   - a token offer must be funded and approved now (token ledgers only);
//   - an item offer of an official collection (Kylix's own code, written not
//     to panic) that registered an approval check must be owned and
//     approved now;
//   - an item offer of any other collection is never checked here, because
//     that would run third-party code: the home page leaves it out, and an
//     offer page keeps it as unverified, after every verified offer.
//
// Crowding (security reviews 2 and 3). Posting an offer is cheap, so one
// account's offers must not push everyone else's out:
//   - the window counts up to matchScanRawLimit newest offers, of which an
//     owner contributes at most matchPerOwnerSeen (kept or skipped as dead
//     or expired); its further offers are passed over without counting, up
//     to matchScanReadLimit offers read in all;
//   - it keeps at most matchPerOwnerWindow offers of one owner;
//   - each wanted-asset bucket keeps at most matchPerOwnerBucket offers of
//     one owner, verified offers first;
//   - an offer may appear in at most matchPerOfferCands candidate rings, so
//     a handful of overlapping offers cannot use up the candidate budget
//     before distinct rings are found;
//   - only rings that close count as search steps, so offers that almost
//     match cost checks but not steps (security review 4, R4-3).
//
// Offers from many different accounts can still fill the window; on the
// home page they must be ready, so they form real rings that anyone may
// settle, and the settler collects their storage deposits.
const (
	matchScanRawLimit   = 100  // max offers counted for the window
	matchScanReadLimit  = 400  // max offers read from storage for the window
	matchScanLimit      = 50   // max offers kept in the search window
	matchPerOwnerSeen   = 8    // max offers of one owner counted (kept or skipped)
	matchPerOwnerWindow = 4    // max offers of one owner in the window
	matchMaxBucket      = 12   // max offers indexed per wanted asset
	matchPerOwnerBucket = 2    // max offers of one owner per wanted asset
	matchPerOfferCands  = 2    // max candidate rings one offer may appear in
	matchMaxSteps       = 500  // max closing rings tried per search (see findHomeRingsFrom)
	matchMaxChecks      = 8000 // max pairs and triples checked per search
	maxHomeRings        = 6    // max rings displayed on the home page
	maxOfferRings       = 6    // max rings displayed on an offer page
	maxCandidates       = 12   // max candidate rings collected before selection
)

// findHomeRings finds up to maxHomeRings disjoint direct rings of 2 or 3
// offers among the newest unexpired offers, every one of them verified ready
// now. It calls no third-party collection code.
func findHomeRings() [][]*Offer {
	return findHomeRingsFrom(newestUnexpiredOffers(0, true))
}

func findHomeRingsFrom(w *window) [][]*Offer {
	if len(w.offers) < 2 {
		return nil
	}
	window := w.offers
	ix := indexByWant(w)

	seen := map[string]bool{}
	uses := map[uint64]int{} // candidate rings each offer appears in
	var cands [][]*Offer
	steps := 0
	add := func(cand []*Offer) {
		k := ringDedupKey(cand)
		if seen[k] {
			return
		}
		for _, o := range cand {
			if uses[o.ID] >= matchPerOfferCands {
				return
			}
		}
		seen[k] = true
		for _, o := range cand {
			uses[o.ID]++
		}
		cands = append(cands, cand)
	}

	// Every pair and triple tried is checked in full before it counts as a
	// step (security review 4, R4-3): a step is a ring that closes, so
	// offers that almost match cannot use up the budget. The loops are
	// bounded by the window and bucket sizes (at most 50 starts, 12 offers
	// per bucket, 12 per pair: 7,800 checks), and by matchMaxChecks.
	checks := 0
	for _, a := range window {
		if steps >= matchMaxSteps || checks >= matchMaxChecks || len(cands) >= maxCandidates {
			break
		}
		if uses[a.ID] >= matchPerOfferCands || !ix.satisfiable(a) {
			continue
		}
		for _, b := range ix.byWant[assetBucketKey(a.Give)] {
			checks++
			if checks > matchMaxChecks || steps >= matchMaxSteps || len(cands) >= maxCandidates || uses[a.ID] >= matchPerOfferCands {
				break
			}
			if uses[b.ID] >= matchPerOfferCands || !directMatch(a, b) {
				continue
			}
			// 2-offer ring: a -> b -> a
			if directMatch(b, a) {
				steps++
				add(canonicalRing([]*Offer{a, b}))
				continue
			}
			// 3-offer ring: a -> b -> c -> a
			for _, c := range ix.byPair[pairKey(b.Give, a.Want)] {
				checks++
				if checks > matchMaxChecks || steps >= matchMaxSteps || len(cands) >= maxCandidates ||
					uses[a.ID] >= matchPerOfferCands || uses[b.ID] >= matchPerOfferCands {
					break
				}
				if c.ID == a.ID || c.Owner == a.Owner || uses[c.ID] >= matchPerOfferCands {
					continue
				}
				if !directMatch(b, c) || !directMatch(c, a) || duplicateGivenItem(a, b, c) {
					continue
				}
				steps++
				add(canonicalRing([]*Offer{a, b, c}))
			}
		}
	}

	if len(cands) == 0 {
		return nil
	}

	// Prefer 3-offer rings over 2-offer rings, then rings with newer offers.
	// len(cands) <= maxCandidates (12), so insertion sort is tiny and cheap.
	for i := 1; i < len(cands); i++ {
		cur := cands[i]
		j := i - 1
		for j >= 0 && ringBefore(cur, cands[j]) {
			cands[j+1] = cands[j]
			j--
		}
		cands[j+1] = cur
	}

	// Pick a non-overlapping subset so each open offer appears once on Home.
	used := map[uint64]bool{}
	var out [][]*Offer
	for _, r := range cands {
		if len(out) >= maxHomeRings {
			break
		}
		overlap := false
		for _, o := range r {
			if used[o.ID] {
				overlap = true
				break
			}
		}
		if overlap {
			continue
		}
		for _, o := range r {
			used[o.ID] = true
		}
		out = append(out, r)
	}
	return out
}

// findRingsForOffer finds up to maxOfferRings direct rings of 2 or 3 offers
// among the newest unexpired offers that include target. Every returned ring
// starts at target. Third-party items are kept unverified, after verified
// offers; no third-party collection code runs.
func findRingsForOffer(target *Offer) [][]*Offer {
	if target == nil || expired(target, runtime.ChainHeight()) {
		return nil
	}
	w := newestUnexpiredOffers(target.ID, false)
	if len(w.offers) == 0 {
		return nil
	}
	ix := indexByWant(w)

	seen := map[string]bool{}
	var out [][]*Offer
	steps := 0

	for _, b := range ix.byWant[assetBucketKey(target.Give)] {
		steps++
		if steps > matchMaxSteps || len(out) >= maxOfferRings {
			break
		}
		if !directMatch(target, b) {
			continue
		}
		if directMatch(b, target) {
			k := ringDedupKey(canonicalRing([]*Offer{target, b}))
			if !seen[k] {
				seen[k] = true
				out = append(out, []*Offer{target, b})
			}
			continue
		}
		for _, c := range ix.byPair[pairKey(b.Give, target.Want)] {
			steps++
			if steps > matchMaxSteps || len(out) >= maxOfferRings {
				break
			}
			if c.ID == target.ID || c.Owner == target.Owner {
				continue
			}
			if !directMatch(b, c) || !directMatch(c, target) {
				continue
			}
			if duplicateGivenItem(target, b, c) {
				continue
			}
			k := ringDedupKey(canonicalRing([]*Offer{target, b, c}))
			if !seen[k] {
				seen[k] = true
				out = append(out, []*Offer{target, b, c})
			}
		}
	}
	return out
}

// readyNow reports whether o may take part in the on-page search, and
// whether it was verified: see the comment on the bounds above. strict
// (the home page) leaves out what cannot be verified without third-party
// code.
func readyNow(o *Offer, strict bool) (ok, verified bool) {
	if o.Give.Kind == ring.Fungible {
		return undeliverable(o) == "", true
	}
	c := getCollection(o.Give.Key)
	if c == nil {
		return false, false
	}
	if IsOfficial(o.Give.Key) && c.approved != nil {
		return undeliverable(o) == "", true
	}
	return !strict, false
}

// newestUnexpiredOffers builds the search window from the newest offers,
// skipping excludeID (see the comment on the bounds above).
func newestUnexpiredOffers(excludeID uint64, strict bool) *window {
	h := runtime.ChainHeight()
	w := newWindow(strict)
	eachOfferBefore(0, func(o *Offer) bool {
		if w.done() {
			return true
		}
		if o.ID != excludeID {
			w.consider(o, h)
		}
		return false
	})
	return w
}

// window collects the search window.
type window struct {
	strict   bool
	offers   []*Offer
	verified map[uint64]bool
	kept     map[address]int
	seen     map[address]int
	counted  int
	read     int
}

func newWindow(strict bool) *window {
	return &window{
		strict:   strict,
		offers:   make([]*Offer, 0, matchScanLimit),
		verified: map[uint64]bool{},
		kept:     map[address]int{},
		seen:     map[address]int{},
	}
}

// done reports whether the window needs no more offers.
func (w *window) done() bool {
	return len(w.offers) >= matchScanLimit || w.counted >= matchScanRawLimit || w.read >= matchScanReadLimit
}

func (w *window) consider(o *Offer, h int64) {
	if w.done() {
		return
	}
	w.read++
	if w.seen[o.Owner] >= matchPerOwnerSeen {
		return // passed over without counting
	}
	w.seen[o.Owner]++
	w.counted++
	if expired(o, h) || w.kept[o.Owner] >= matchPerOwnerWindow {
		return
	}
	ok, verified := readyNow(o, w.strict)
	if !ok {
		return
	}
	w.kept[o.Owner]++
	w.verified[o.ID] = verified
	w.offers = append(w.offers, o)
}

// index is the search window bucketed for the ring search.
type index struct {
	// byWant: offers by wanted asset. Within a bucket, verified offers come
	// first, then lower minimums (an offer asking for more than anyone gives
	// cannot close a ring, so it must not take a place another could use),
	// then newer offers; at most matchPerOwnerBucket per owner and
	// matchMaxBucket in all.
	byWant map[string][]*Offer
	// byPair: the same, by wanted and given asset together, so the last
	// offer of a 3-offer ring is looked for only among offers that give
	// what the first one wants.
	byPair map[string][]*Offer
	// given: the largest amount given of each asset (1 for an item), so an
	// offer whose minimum nobody in the window meets costs no search steps.
	given map[string]int64
}

func pairKey(want, give ring.Asset) string { return assetBucketKey(want) + ">" + assetBucketKey(give) }

func indexByWant(w *window) *index {
	ix := &index{byWant: map[string][]*Offer{}, byPair: map[string][]*Offer{}, given: map[string]int64{}}
	all := make(map[string][]*Offer, len(w.offers))
	var keys []string
	for _, o := range w.offers {
		k := assetBucketKey(o.Want)
		if _, ok := all[k]; !ok {
			keys = append(keys, k)
		}
		all[k] = append(all[k], o)
		amt := o.Give.Amount
		if o.Give.Kind == ring.Item {
			amt = 1
		}
		if gk := assetBucketKey(o.Give); amt > ix.given[gk] {
			ix.given[gk] = amt
		}
	}
	for _, k := range keys {
		list := all[k]
		// Insertion sort: stable, and the window holds at most 50 offers.
		for i := 1; i < len(list); i++ {
			cur := list[i]
			j := i - 1
			for j >= 0 && bucketBefore(w, cur, list[j]) {
				list[j+1] = list[j]
				j--
			}
			list[j+1] = cur
		}
		perOwner := map[address]int{}
		perPairOwner := map[string]int{}
		for _, o := range list {
			if len(ix.byWant[k]) < matchMaxBucket && perOwner[o.Owner] < matchPerOwnerBucket {
				ix.byWant[k] = append(ix.byWant[k], o)
				perOwner[o.Owner]++
			}
			pk := pairKey(o.Want, o.Give)
			if len(ix.byPair[pk]) < matchMaxBucket && perPairOwner[pk+o.Owner.String()] < matchPerOwnerBucket {
				ix.byPair[pk] = append(ix.byPair[pk], o)
				perPairOwner[pk+o.Owner.String()]++
			}
		}
	}
	return ix
}

// satisfiable reports whether some offer in the window gives what o wants,
// at least o's minimum.
func (ix *index) satisfiable(o *Offer) bool {
	need := o.Want.Amount
	if o.Want.Kind == ring.Item {
		need = 1
	}
	return ix.given[assetBucketKey(o.Want)] >= need
}

func bucketBefore(w *window, a, b *Offer) bool {
	if w.verified[a.ID] != w.verified[b.ID] {
		return w.verified[a.ID]
	}
	return a.Want.Amount < b.Want.Amount
}

func assetBucketKey(a ring.Asset) string {
	return kindDigit(a.Kind) + "|" + a.Key + "|" + a.ID
}

// directMatch reports whether offer a can feed offer b directly (no GnoSwap).
func directMatch(a, b *Offer) bool {
	if a.ID == b.ID || a.Owner == b.Owner {
		return false
	}
	if !a.Give.SameAs(b.Want) {
		return false
	}
	if a.Give.Kind == ring.Fungible && a.Give.Amount < b.Want.Amount {
		return false
	}
	return true
}

func duplicateGivenItem(a, b, c *Offer) bool {
	if a.Give.Kind == ring.Item && (a.Give.SameAs(b.Give) || a.Give.SameAs(c.Give)) {
		return true
	}
	if b.Give.Kind == ring.Item && b.Give.SameAs(c.Give) {
		return true
	}
	return false
}

// canonicalRing rotates offs so the smallest offer ID comes first.
func canonicalRing(offs []*Offer) []*Offer {
	minIdx := 0
	for i := 1; i < len(offs); i++ {
		if offs[i].ID < offs[minIdx].ID {
			minIdx = i
		}
	}
	if minIdx == 0 {
		return offs
	}
	res := make([]*Offer, len(offs))
	for i := range offs {
		res[i] = offs[(minIdx+i)%len(offs)]
	}
	return res
}

func ringDedupKey(offs []*Offer) string {
	ids := make([]uint64, len(offs))
	for i, o := range offs {
		ids[i] = o.ID
	}
	return ring.FormatOfferIDs(ids)
}

func maxRingOfferID(offs []*Offer) uint64 {
	var m uint64
	for _, o := range offs {
		if o.ID > m {
			m = o.ID
		}
	}
	return m
}

func ringBefore(a, b []*Offer) bool {
	if len(a) != len(b) {
		return len(a) > len(b)
	}
	ma, mb := maxRingOfferID(a), maxRingOfferID(b)
	if ma != mb {
		return ma > mb
	}
	return a[0].ID < b[0].ID
}

package kylix

import (
	"gno.land/r/nym-gfanton001/gnotif/v1"
)

const (
	// OfferSettledEvent is emitted once per owner when their offer settles in
	// a ring, so gnotif can deliver a notification directly to each owner.
	OfferSettledEvent = "OfferSettled"

	offerSettledTriggerName = "offer_settled"
)

// EnableNotifications opens Kylix's gnotif handle and registers the
// OfferSettled notification trigger.
//
// Kylix keeps no admin: gnotif itself enforces that this call is signed with
// the namespace owner's account key (not a session key) and sent straight to
// Kylix. Calling it from init is avoided because gno test runs without
// namespace ownership and a gnotif outage must never block deployment.
//
// Only settled offers trigger notifications. A "matching offer posted"
// trigger is deliberately omitted: PostIntent does not check balances or
// approvals, so an attacker could post and cancel unapproved offers at near
// zero cost to spam another trader's notifications, and every PostIntent
// would have to scan the book.
func EnableNotifications(cur realm) {
	guard(cur)
	me := cur.Sub(gnotif.Subpath)
	h := gnotif.Open(cross(me))
	h.Set(cross(me), offerSettledTriggerName, gnotif.Trigger{
		Event: OfferSettledEvent,
		Param: "owner",
		Title: "Offer settled",
		Body:  "Offer #{id}: gave {gave}, received {received}",
		Link:  webPath(),
	})
}

package kylix

import (
	"chain"
	"chain/runtime"
	"strconv"
)

// PruneIntent deletes an expired offer. Anyone may call it, and the storage
// deposit the offer released goes to the caller. It reads only Kylix's own
// storage and calls no collection or token code, so pruning can never cost
// the caller more than the offer's own bytes, and no collection can make an
// expired offer impossible to prune. An offer that has not expired can only
// be cancelled by its owner or settled in a ring.
func PruneIntent(cur realm, id uint64) {
	guard(cur)
	o := mustOpen(id)
	if h := runtime.ChainHeight(); !expired(o, h) {
		panic("kylix: offer " + u64(id) + " has not expired; it can be pruned after height " +
			strconv.FormatInt(o.Expiry, 10))
	}
	removeOffer(o.ID)
	chain.Emit("IntentPruned", "id", u64(id), "owner", o.Owner.String(), "reason", "expired",
		"pruner", cur.Previous().Address().String())
}

package kylix

import (
	"chain/runtime"
	"html"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
	"gno.land/r/sys/users"
)

const (
	pageOffers       = 50 // open offers per page, newest first
	maxFormAssetOpts = 50 // cap dropdown choices on the post page
	homeCollections  = 10 // collections listed on the home page
	pageCollections  = 50 // collections per page on the collections page
)

// Render serves Kylix's gnoweb pages:
//   - ""             Home: pitch, 3-step guide, ready rings, open offers, collections
//   - "offers/<id>"  Older open offers before <id>
//   - "offer/<id>"   One offer: details, readiness, approve step, matching rings, actions
//   - "ring/<ids>"   One ring (e.g. "ring/1,2,3"): large graph, swaps in words, readiness, settle
//   - "post"         Offer builder (approve address calculator + TxLinks + gnokey form)
//   - "collections"  Registered collections, official first (paged with ?after=<key>)
//   - "about"        How settlement works, custody model, GnoSwap fees, collection plug-in guide
//
// Home ("", "offers/<id>") never calls third-party collection code. It
// reads Kylix's own storage, token ledgers and official collections (to check
// that offers are still ready), and gno.land/r/sys/users for display names.
// Only a third-party item's own offer and ring pages, and settling, run that
// collection's code.
// Every string from a user or collection is sanitized for the slot it lands in.
func Render(path string) string {
	route, rawQuery, _ := strings.Cut(path, "?")
	switch {
	case route == "":
		return renderHome(0)
	case strings.HasPrefix(route, "offers/"):
		before, err := strconv.ParseUint(strings.TrimPrefix(route, "offers/"), 10, 64)
		if err != nil {
			return renderNotFound("No such page.")
		}
		return renderHome(before)
	case strings.HasPrefix(route, "offer/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(route, "offer/"), 10, 64)
		if err != nil {
			return renderNotFound("No such offer.")
		}
		return renderOffer(id)
	case strings.HasPrefix(route, "ring/"):
		return renderRing(strings.TrimPrefix(route, "ring/"))
	case route == "post":
		return renderPost(rawQuery)
	case route == "collections":
		q, _ := url.ParseQuery(rawQuery)
		return renderCollections(q.Get("after"))
	case route == "about" || route == "how":
		return renderAbout()
	}
	return renderNotFound("Page not found.")
}

func renderNotFound(msg string) string {
	return "# Not found\n\n" + navBar("") + "\n\n" + msg + "\n\n[Back to Kylix](" + webPath() + ")\n"
}

func renderHome(before uint64) string {
	cache := map[string]string{}
	var sb strings.Builder
	sb.WriteString("# Kylix\n\n")
	sb.WriteString(navBar("home") + "\n\n")
	sb.WriteString("Swap tokens and collectibles in a circle: post what you offer and what you want, and when two to six offers close a ring, everyone swaps in one transaction — with nothing leaving your wallet until settlement.\n\n")

	sb.WriteString(gnoButton(webPath()+":post", "Post an offer", "success") + " ")
	sb.WriteString(gnoButton(demoWebPath(), "Get free demo assets", "outline") + " ")
	sb.WriteString(gnoButton(webPath()+":about", "How it works", "outline") + "\n\n")

	h := runtime.ChainHeight()
	var table string
	var next uint64

	if before == 0 {
		// One B+ tree pass feeds both the open offers table (the newest
		// pageOffers) and the ring search window, which may read further
		// back (see newestUnexpiredOffers).
		page := make([]*Offer, 0, pageOffers)
		w := newWindow(true)
		eachOfferBefore(0, func(o *Offer) bool {
			if len(page) == pageOffers && next == 0 {
				next = o.ID + 1
			}
			if len(page) < pageOffers {
				page = append(page, o)
			}
			w.consider(o, h)
			return len(page) == pageOffers && next != 0 && w.done()
		})

		sb.WriteString("<gno-columns>\n")
		sb.WriteString("<gno-frame>\n### 1. Approve\nAllow your offer's own address to move only the token amount or item you offer. Your assets stay in your wallet.\n</gno-frame>\n")
		sb.WriteString("<gno-columns-sep />\n")
		sb.WriteString("<gno-frame>\n### 2. Post your offer\nState what you give and the minimum you want back. You can cancel an open offer at any time.\n</gno-frame>\n")
		sb.WriteString("<gno-columns-sep />\n")
		sb.WriteString("<gno-frame>\n### 3. Settle the ring\nWhen two to six offers form a closed circle, anyone can settle it. Every swap happens together, or nothing moves.\n</gno-frame>\n")
		sb.WriteString("</gno-columns>\n\n")

		sb.WriteString("## Ready to settle\n\n")
		rings := findHomeRingsFrom(w)
		if len(rings) == 0 {
			sb.WriteString("No 2- or 3-offer direct ring of ready offers is open among the newest offers right now. [Post a matching offer](" + webPath() + ":post) or grab test tokens and a Relic from the [demo faucet](" +
				demoWebPath() + ").\n\n")
		} else {
			writeRingCards(&sb, rings, cache)
			sb.WriteString("Showing 2- and 3-offer direct rings found among the newest open offers, every offer checked ready just now. ")
			sb.WriteString("This page checks items of official collections only; rings with other collections' items are listed on those offers' own pages. ")
			sb.WriteString("Longer rings (up to 6 offers) and rings that need a GnoSwap swap are found by programs that search off chain.\n\n")
		}
		table = renderOfferRows(page, h, cache)
	} else {
		table, next = offerTableWithCache(before, pageOffers, cache)
	}

	sb.WriteString("## Open offers\n\n")
	if n := offers.Size(); n > 0 {
		sb.WriteString(strconv.Itoa(n) + " open " + pluralWord(n, "offer", "offers") + " in the book")
		if before != 0 {
			sb.WriteString(" · [← Newest offers](" + webPath() + ")")
		}
		sb.WriteString(".\n\n")
	}
	sb.WriteString(table)
	if next != 0 {
		sb.WriteString("\n[Older offers →](" + webPath() + ":offers/" + u64(next) + ")\n")
	}

	sb.WriteString("\n## Collections\n\n")
	sb.WriteString(collectionList())
	sb.WriteString("\n[Collection details & adapter trust guide →](" + webPath() + ":collections)\n\n")

	sb.WriteString("> [!TIP] Try Kylix in two minutes\n")
	sb.WriteString("> Claim free OBOL, DRACHMA and a Kylix Relic from the [demo faucet](" + demoWebPath() + "), then post an offer. ")
	sb.WriteString("Want browser alerts when your offers settle? Opt in on [gnotif](https://gnotif.xyz).\n")
	return sb.String()
}

func writeRingCards(sb *strings.Builder, rings [][]*Offer, cache map[string]string) {
	for i := 0; i < len(rings); i += 2 {
		sb.WriteString("<gno-columns>\n")
		writeOneRingCard(sb, rings[i], cache)
		if i+1 < len(rings) {
			sb.WriteString("<gno-columns-sep />\n")
			writeOneRingCard(sb, rings[i+1], cache)
		}
		sb.WriteString("</gno-columns>\n\n")
	}
}

func writeOneRingCard(sb *strings.Builder, r []*Offer, cache map[string]string) {
	ids := offerIDList(r)
	hops := make([]ring.GraphHop, len(r))
	for i, o := range r {
		hops[i] = ring.GraphHop{
			From:    ownerPlain(o.Owner, cache),
			Give:    graphAsset(o.Give),
			Note:    svgHint(assetHint(o.Give)),
			OfferID: o.ID,
		}
	}
	uri := ring.GraphDataURI(hops, ring.GraphThumb)
	sb.WriteString("<gno-frame>\n")
	sb.WriteString("### " + strconv.Itoa(len(r)) + "-offer ring (" + ids + ")\n\n")
	if uri != "" {
		sb.WriteString("![Ring " + ids + "](" + uri + ")\n\n")
	}
	for i, o := range r {
		next := r[(i+1)%len(r)]
		sb.WriteString("- " + ownerMarkdown(o.Owner, cache) + " gives **" + sanitize.InlineText(shortAsset(o.Give)) +
			"** to " + ownerMarkdown(next.Owner, cache) + "\n")
	}
	// The button leads to the ring page, which shows every asset's full key
	// and the settle command, rather than settling from here.
	sb.WriteString("\n" + gnoButton(webPath()+":ring/"+ids, "Review and settle", "success") + "\n")
	sb.WriteString("</gno-frame>\n")
}

// offerTable renders up to limit open offers with id < before (all when
// before is 0), newest first, as a markdown table. next is the before value
// for the following page, or 0 when there is none.
func offerTable(before uint64, limit int) (md string, next uint64) {
	return offerTableWithCache(before, limit, map[string]string{})
}

func offerTableWithCache(before uint64, limit int, cache map[string]string) (md string, next uint64) {
	h := runtime.ChainHeight()
	page := make([]*Offer, 0, limit)
	eachOfferBefore(before, func(o *Offer) bool {
		if len(page) == limit {
			next = o.ID + 1 // an older offer exists; the next page starts at it
			return true
		}
		page = append(page, o)
		return false
	})
	return renderOfferRows(page, h, cache), next
}

func renderOfferRows(page []*Offer, h int64, cache map[string]string) string {
	if len(page) == 0 {
		return "No open offers yet. [Post the first offer](" + webPath() + ":post).\n"
	}
	var sb strings.Builder
	sb.WriteString("| Offer | Owner | Gives | Wants | Expiry |\n|---|---|---|---|---|\n")
	for _, o := range page {
		sb.WriteString("| [" + u64(o.ID) + "](" + webPath() + ":offer/" + u64(o.ID) + ") | ")
		sb.WriteString(ownerTableCell(o.Owner, cache) + " | ")
		sb.WriteString(sanitize.TableCell(shortAsset(o.Give)) + " | ")
		sb.WriteString(sanitize.TableCell(shortWant(o.Want)) + " | ")
		sb.WriteString(expiryString(o, h) + " |\n")
	}
	return sb.String()
}

// collectionList renders the registered collections as a markdown list,
// official ones first, at most homeCollections of them, with a link to the
// collections page for the rest.
func collectionList() string {
	if collections.Size() == 0 {
		return "No collections registered.\n"
	}
	var sb strings.Builder
	keys, more := collectionKeys("", homeCollections)
	for _, key := range keys {
		c := getCollection(key)
		sb.WriteString("- **" + sanitize.InlineText(c.name) + "** (" + sanitize.InlineCode(key) + "): " +
			collectionLabel(key) + "\n")
	}
	if more {
		sb.WriteString("- … and " + strconv.Itoa(collections.Size()-len(keys)) + " more on the [collections page](" + webPath() + ":collections)\n")
	}
	return sb.String()
}

// collectionKeys lists up to limit collection keys, official ones (under
// Kylix's own namespace) first, then the others in key order, starting
// after the key after ("" for the start). more reports whether any follow.
func collectionKeys(after string, limit int) (keys []string, more bool) {
	ns := namespacePrefix()
	type span struct{ start, end string }
	spans := []span{{"", ""}}
	if ns != "" {
		nsEnd := ns + "\xff"
		spans = []span{{ns, nsEnd}, {"", ns}, {nsEnd, ""}}
	}
	in := func(sp span, k string) bool { return k >= sp.start && (sp.end == "" || k < sp.end) }
	from := 0
	if after != "" {
		for i, sp := range spans {
			if in(sp, after) {
				from = i
				spans[i].start = after + "\x00"
				break
			}
		}
	}
	for _, sp := range spans[from:] {
		collections.Iterate(sp.start, sp.end, func(key string, _ any) bool {
			if len(keys) >= limit {
				more = true
				return true
			}
			keys = append(keys, key)
			return false
		})
		if more {
			break
		}
	}
	return keys, more
}

// collectionKind is a collection's trust label, the same words on every
// page, in ring captions and in the export: "official collection" or
// "official adapter" for one registered under Kylix's own namespace,
// "third-party collection" or "third-party adapter" for any other.
// Official is a label, not a gate: anyone may register a collection under
// their own namespace, and pick any display name.
func collectionKind(key string) string {
	c := getCollection(key)
	switch {
	case c == nil:
		return "unregistered"
	case c.target == "" && IsOfficial(key):
		return "official collection"
	case c.target == "":
		return "third-party collection"
	case IsOfficial(key):
		return "official adapter"
	}
	return "third-party adapter"
}

// collectionLabel is collectionKind, naming an adapter's target.
func collectionLabel(key string) string {
	c := getCollection(key)
	if c == nil || c.target == "" {
		return collectionKind(key)
	}
	return collectionKind(key) + " for " + sanitize.InlineText(c.target)
}

func wantString(a ring.Asset) string {
	if a.Kind == ring.Fungible {
		return "at least " + a.String()
	}
	return a.String()
}

func shortWant(a ring.Asset) string {
	if a.Kind == ring.Fungible {
		return "at least " + shortAsset(a)
	}
	return shortAsset(a)
}

// shortAsset names an asset in words with a hint of the realm it lives in,
// because symbols and display names are chosen by whoever deploys: anyone
// can make a token called GNS or a collection called Kylix Relics. Tokens:
// "100 OBOL (g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylixdemo)". Items carry their collection's label
// too: "Kylix Relics #relic-2 (official collection, g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylixdemo)".
// Pages where someone decides to sign show the full key as well (keyedAsset).
func shortAsset(a ring.Asset) string {
	if a.Kind == ring.Item {
		return graphAsset(a) + " (" + collectionKind(a.Key) + ", " + realmHint(a.Key) + ")"
	}
	return graphAsset(a) + " (" + realmHint(tokenRealmPath(a.Key)) + ")"
}

// keyedAsset is for the pages where someone decides: the short name in bold,
// then the label and the full key in code. Markdown, already escaped.
func keyedAsset(a ring.Asset, atLeast bool) string {
	name := graphAsset(a)
	if atLeast && a.Kind == ring.Fungible {
		name = "at least " + name
	}
	if a.Kind == ring.Item {
		return "**" + sanitize.InlineText(name) + "** (" + collectionKind(a.Key) + " " + sanitize.InlineCode(a.Key) + ")"
	}
	return "**" + sanitize.InlineText(name) + "** (token " + sanitize.InlineCode(a.Key) + ")"
}

// graphAsset is the bare name, for the ring pictures, which draw the realm
// hint (assetHint) on a second line.
func graphAsset(a ring.Asset) string {
	if a.Kind == ring.Item {
		if name := CollectionName(a.Key); name != "" {
			return name + " #" + a.ID
		}
		return a.Key + "#" + a.ID
	}
	return strconv.FormatInt(a.Amount, 10) + " " + shortTokenSymbol(a.Key)
}

// assetHint is the realm hint of an asset: its token realm or collection.
func assetHint(a ring.Asset) string {
	if a.Kind == ring.Item {
		return realmHint(a.Key)
	}
	return realmHint(tokenRealmPath(a.Key))
}

// svgHint fits a realm hint into a ring picture without making it
// ambiguous. The namespace is what tells owners apart: a name namespace is
// kept whole, and only a namespace that is a valid address (checked as an
// address, not by its look: a registered name may start with "g1") keeps its
// first 8 and last 6 characters, the end being checksum, so matching both
// means grinding about 2^60 keys. Only the rest of the path, which the same
// owner controls anyway, is shortened. A hint is then at most 64 + 15 runes,
// under the picture's 80-rune limit for notes.
func svgHint(hint string) string {
	ns, rest, _ := strings.Cut(hint, "/")
	if address(ns).IsValid() {
		ns = ns[:8] + "…" + ns[len(ns)-6:]
	}
	if rest == "" {
		return ns
	}
	if r := []rune(rest); len(r) > 14 {
		rest = "…" + string(r[len(r)-13:])
	}
	return ns + "/" + rest
}

// realmHint shortens a realm path to what identifies it: the namespace and
// the rest of the path, without "gno.land/r/". The namespace comes first,
// and only its owner can deploy under it, so a look-alike cannot share the
// hint's beginning: "gnoland/wugnot" vs "evil/gnoland/wugnot".
func realmHint(pkgPath string) string {
	s := strings.TrimPrefix(pkgPath, "gno.land/")
	s = strings.TrimPrefix(s, "r/")
	if s == "" {
		return pkgPath
	}
	return s
}

func shortTokenSymbol(key string) string {
	if i := strings.LastIndex(key, "."); i >= 0 && i+1 < len(key) {
		return key[i+1:]
	}
	return key
}

func tokenRealmPath(key string) string {
	if i := strings.LastIndex(key, "."); i > 0 {
		return key[:i]
	}
	return ""
}

func assetNote(a ring.Asset) string {
	if a.Kind != ring.Item {
		return ""
	}
	c := getCollection(a.Key)
	if c == nil {
		return ""
	}
	return " (" + sanitize.InlineText(c.name) + ", " + collectionLabel(a.Key) + ")"
}

// expiryString is the short form for tables: "in about 3 days" or
// "expired".
func expiryString(o *Offer, h int64) string {
	if expired(o, h) {
		return "expired"
	}
	return blocksAhead(o.Expiry - h)
}

// expiryLong adds the block height: "in about 3 days (block height 1234)".
func expiryLong(o *Offer, h int64) string {
	if expired(o, h) {
		return "expired at block height " + strconv.FormatInt(o.Expiry, 10)
	}
	return blocksAhead(o.Expiry-h) + " (block height " + strconv.FormatInt(o.Expiry, 10) + ")"
}

// blocksAhead says roughly how long n blocks take, assuming BlocksPerDay,
// rounded to the nearest hour or day (a 7-day offer a few blocks old still
// reads "in about 7 days").
func blocksAhead(n int64) string {
	const perHour = BlocksPerDay / 24
	hours := (n + perHour/2) / perHour
	days := (n + BlocksPerDay/2) / BlocksPerDay
	switch {
	case hours < 1:
		return "in less than an hour"
	case hours == 1:
		return "in about an hour"
	case hours < 24:
		return "in about " + strconv.FormatInt(hours, 10) + " hours"
	case days == 1:
		return "in about a day"
	}
	return "in about " + strconv.FormatInt(days, 10) + " days"
}

// expiryInputHint explains PostIntent's expiry argument on the post forms.
func expiryInputHint() string {
	h := runtime.ChainHeight()
	return "Expiry block height: 0 for the default of about 7 days, at most about 30 days ahead (now " +
		strconv.FormatInt(h, 10) + ", latest " + strconv.FormatInt(h+MaxExpiryBlocks, 10) + ")"
}

// webPath is this realm's gnoweb path, e.g. "/r/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylix".
func webPath() string {
	return pkgWebPath(selfPath)
}

func pkgWebPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i:]
	}
	return pkgPath
}

func demoRealmPath() string {
	ns := namespacePrefix()
	if ns == "" {
		return ""
	}
	return ns + "kylixdemo"
}

func demoWebPath() string {
	p := demoRealmPath()
	if p == "" {
		return "/r/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylixdemo"
	}
	return pkgWebPath(p)
}

func navBar(active string) string {
	items := []struct {
		key, label, href string
	}{
		{"home", "Home", webPath()},
		{"post", "Post an offer", webPath() + ":post"},
		{"collections", "Collections", webPath() + ":collections"},
		{"about", "How it works", webPath() + ":about"},
		{"demo", "Demo faucet", demoWebPath()},
	}
	var parts []string
	for _, it := range items {
		if it.key == active {
			parts = append(parts, "**"+it.label+"**")
		} else {
			parts = append(parts, "["+it.label+"]("+it.href+")")
		}
	}
	return strings.Join(parts, " · ")
}

func lookupUsername(addr address, cache map[string]string) string {
	s := addr.String()
	if name, ok := cache[s]; ok {
		return name
	}
	var name string
	if u := users.ResolveAddress(addr); u != nil {
		name = sanitize.UserName(u.Name())
	}
	cache[s] = name
	return name
}

func ownerPlain(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "@" + name
	}
	return shortAddr(addr)
}

func ownerMarkdown(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.InlineText(name) + "](/u/" + url.PathEscape(name) + ")"
	}
	return "`" + shortAddr(addr) + "`"
}

func ownerFullMarkdown(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.InlineText(name) + "](/u/" + url.PathEscape(name) + ") (`" + addr.String() + "`)"
	}
	return "`" + addr.String() + "`"
}

func ownerTableCell(addr address, cache map[string]string) string {
	if name := lookupUsername(addr, cache); name != "" {
		return "[@" + sanitize.TableCell(name) + "](/u/" + url.PathEscape(name) + ")"
	}
	return "`" + shortAddr(addr) + "`"
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 13 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

func offerIDList(offs []*Offer) string {
	ids := make([]uint64, len(offs))
	for i, o := range offs {
		ids[i] = o.ID
	}
	return ring.FormatOfferIDs(ids)
}

// txLink builds a GnoConnect / gnoweb $help transaction link with query-escaped
// argument pairs (k1, v1, k2, v2, ...).
func txLink(realmWebPath, fn string, kv ...string) string {
	var sb strings.Builder
	sb.WriteString(realmWebPath)
	sb.WriteString("$help&func=")
	sb.WriteString(url.QueryEscape(fn))
	for i := 0; i+1 < len(kv); i += 2 {
		sb.WriteByte('&')
		sb.WriteString(url.QueryEscape(kv[i]))
		sb.WriteByte('=')
		sb.WriteString(url.QueryEscape(kv[i+1]))
	}
	return sb.String()
}

func gnoButton(href, label, variant string) string {
	s := `<gno-button href="` + attrEscape(href) + `" label="` + attrEscape(label) + `"`
	if variant != "" {
		s += ` variant="` + attrEscape(variant) + `"`
	}
	return s + ` />`
}

func gnoInput(name, placeholder, value string, required, readonly bool) string {
	s := `<gno-input name="` + attrEscape(name) + `" placeholder="` + attrEscape(placeholder) + `"`
	if value != "" {
		s += ` value="` + attrEscape(value) + `"`
	}
	if required {
		s += ` required="true"`
	}
	if readonly {
		s += ` readonly="true"`
	}
	return s + " />\n"
}

func gnoSelectOpt(name, value, description string, selected, required bool) string {
	s := `<gno-select name="` + attrEscape(name) + `" value="` + attrEscape(value) + `"`
	if description != "" {
		s += ` description="` + attrEscape(description) + `"`
	}
	if selected {
		s += ` selected="true"`
	}
	if required {
		s += ` required="true"`
	}
	return s + " />\n"
}

func attrEscape(s string) string {
	return html.EscapeString(sanitize.StripBidiAndZeroWidth(s))
}

func pluralWord(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

package kylix

import (
	"chain/runtime"
	"net/url"
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/sys/users"
)

// renderOffer renders one open offer: details, live deliverability check,
// exact approve step, rings that would close with it, and cancel/settle actions.
func renderOffer(id uint64) string {
	o := loadOffer(id)
	if o == nil {
		return "# Offer " + u64(id) + "\n\n" + navBar("") +
			"\n\nThis offer is not open: it was settled, cancelled or pruned, or never existed.\n\n[Back to Kylix](" + webPath() + ")\n"
	}

	cache := map[string]string{}
	h := runtime.ChainHeight()
	slot := SlotAddress(o.Owner, o.Nonce)
	target := ApproveTarget(o.Owner, o.Nonce, o.Give.Key)

	isExp := expired(o, h)
	why := ""
	if !isExp {
		why = undeliverable(o)
	}

	var sb strings.Builder
	sb.WriteString("# Offer " + u64(o.ID) + "\n\n")
	sb.WriteString(navBar("") + "\n\n")

	// Status banner.
	switch {
	case isExp:
		sb.WriteString("> [!WARNING] Expired\n> This offer expired at block height " + strconv.FormatInt(o.Expiry, 10) +
			" (current height " + strconv.FormatInt(h, 10) + "). It can no longer swap, and anyone can remove it from the book; whoever does gets its storage deposit back.\n\n")
	case why != "":
		sb.WriteString("> [!WARNING] Needs action before it can swap\n> " + sanitize.InlineText(plainSwapReason(why)) + "\n\n")
	default:
		sb.WriteString("> [!SUCCESS] Ready to swap\n> The owner holds the offered asset")
		if o.Give.Kind == ring.Fungible {
			sb.WriteString(" and has approved the offer's swap address.")
		} else if c := getCollection(o.Give.Key); c != nil && c.approved != nil {
			sb.WriteString(" and has approved the offer's swap address.")
		} else {
			sb.WriteString(". This collection has no read-only approval check, so approval is verified at settlement.")
		}
		sb.WriteString("\n\n")
	}

	// Offer summary.
	sb.WriteString("## Details\n\n")
	sb.WriteString("- **Owner:** " + ownerFullMarkdown(o.Owner, cache) + "\n")
	sb.WriteString("- **Gives:** " + keyedAsset(o.Give, false) + assetNote(o.Give) + "\n")
	sb.WriteString("- **Wants:** " + keyedAsset(o.Want, true) + assetNote(o.Want) + "\n")
	sb.WriteString("- **Expires:** " + expiryLong(o, h) + "\n")
	sb.WriteString("- **Address to approve:** `" + target.String() + "`\n")
	if target != slot {
		sb.WriteString("- **Offer's own address:** `" + slot.String() + "` (offer number " + u64(o.Nonce) +
			" of this owner; this collection trades through an adapter, so approve the address above, not this one)\n")
	}
	if o.ViaSession {
		sb.WriteString("- **Session key:** posted with a session key (cancelling still requires the account key)\n")
	}

	// Approve step.
	sb.WriteString("\n## Approve step for this offer\n\n")
	writeApproveInstructions(&sb, o.Give, target, slot)

	// Matching rings.
	sb.WriteString("\n## Rings that close with this offer\n\n")
	if isExp {
		sb.WriteString("Expired offers cannot settle.\n")
	} else {
		rings := findRingsForOffer(o)
		if len(rings) == 0 {
			sb.WriteString("No 2- or 3-offer direct ring closes with this offer among the newest " + strconv.Itoa(matchScanLimit) +
				" offers right now. Longer rings (up to 6 offers) and rings that need a GnoSwap swap are found by programs that search off chain.\n")
		} else {
			for _, r := range rings {
				ids := offerIDList(r)
				sb.WriteString("- **" + strconv.Itoa(len(r)) + "-offer ring** (`" + ids + "`): ")
				for i, ro := range r {
					if i > 0 {
						sb.WriteString(" → ")
					}
					sb.WriteString(ownerMarkdown(ro.Owner, cache) + " gives " + sanitize.InlineText(shortAsset(ro.Give)))
				}
				sb.WriteString("\n  " + gnoButton(webPath()+":ring/"+ids, "Review and settle", "success") + "\n")
			}
		}
	}

	// Actions.
	sb.WriteString("\n## Actions\n\n")
	sb.WriteString(gnoButton(txLink(webPath(), "CancelIntent", "id", u64(o.ID)), "Cancel offer (owner only)", "caution outline"))
	if isExp {
		sb.WriteString(" " + gnoButton(txLink(webPath(), "PruneIntent", "id", u64(o.ID)), "Remove expired offer", "warning outline"))
	}
	sb.WriteString("\n\nCancelling withdraws your offer and returns its storage deposit to you. It calls no other realm, so nothing can block it. ")
	sb.WriteString("Once an offer has expired, anyone can remove it and collect its deposit; that also calls no other realm.\n\n")

	sb.WriteString("<gno-form exec=\"CancelIntent\">\n")
	sb.WriteString(gnoInput("id", "Offer ID", u64(o.ID), true, true))
	sb.WriteString("</gno-form>\n")

	return sb.String()
}

func writeApproveInstructions(sb *strings.Builder, give ring.Asset, target, slot address) {
	demo := demoRealmPath()
	switch give.Kind {
	case ring.Fungible:
		sym := shortTokenSymbol(give.Key)
		tRealm := tokenRealmPath(give.Key)
		sb.WriteString("Allow `" + target.String() + "` to move **exactly " + strconv.FormatInt(give.Amount, 10) + " " +
			sanitize.InlineText(sym) + "** (token " + sanitize.InlineCode(give.Key) + ") from your wallet: not more, or the offer will not settle. Only this offer can spend that allowance.\n\n")
		if demo != "" && tRealm == demo && (sym == "OBOL" || sym == "DRACHMA") {
			sb.WriteString(gnoButton(
				txLink(demoWebPath(), "Approve", "symbol", sym, "spender", target.String(), "amount", strconv.FormatInt(give.Amount, 10)),
				"Approve "+strconv.FormatInt(give.Amount, 10)+" "+sym+" (demo)",
				"info",
			) + "\n")
		} else if tRealm != "" {
			sb.WriteString(gnoButton(pkgWebPath(tRealm)+"$help", "Open token realm ($help)", "info") +
				" — call `Approve` with spender `" + target.String() + "` and amount exactly `" + strconv.FormatInt(give.Amount, 10) + "`.\n")
		}
	case ring.Item:
		c := getCollection(give.Key)
		if c != nil && c.target != "" {
			sb.WriteString("This collection trades through an adapter (" + sanitize.InlineCode(give.Key) + "). ")
			sb.WriteString("Approve the adapter's address for this offer, `" + target.String() + "` (not the offer's own address `" + slot.String() +
				"`) for item " + sanitize.InlineCode(give.ID) + " in " + sanitize.InlineCode(c.target) + ".\n\n")
			sb.WriteString(gnoButton(pkgWebPath(c.target)+"$help", "Open target collection ($help)", "info") + "\n")
		} else {
			sb.WriteString("Approve `" + target.String() + "` for item " + sanitize.InlineCode(give.ID) + " in " +
				sanitize.InlineCode(give.Key) + ".\n\n")
			if demo != "" && give.Key == demo {
				sb.WriteString(gnoButton(
					txLink(demoWebPath(), "ApproveRelic", "spender", target.String(), "id", give.ID),
					"Approve Relic "+give.ID+" (demo)",
					"info",
				) + "\n")
			} else {
				sb.WriteString(gnoButton(pkgWebPath(give.Key)+"$help", "Open collection realm ($help)", "info") + "\n")
			}
		}
	}
}

// renderRing renders a ring page ("ring/1,2,3"): large SVG graph, each swap in
// plain English, live readiness check per swap, and settle links/form.
func renderRing(rawIDs string) string {
	idList, err := ring.ParseOfferIDs(rawIDs)
	if err != nil {
		return "# Ring\n\n" + navBar("") + "\n\nInvalid offer list: " +
			sanitize.InlineText(plainSwapReason(err.Error())) + "\n\n[Back to Kylix](" + webPath() + ")\n"
	}

	cache := map[string]string{}
	height := runtime.ChainHeight()
	n := len(idList)
	offs := make([]*Offer, n)
	legs := make([]ring.Leg, n)
	var problems []string

	for i, id := range idList {
		o := loadOffer(id)
		if o == nil {
			problems = append(problems, "Offer #"+u64(id)+" is not open (already settled, cancelled, pruned, or unknown).")
			continue
		}
		if expired(o, height) {
			problems = append(problems, "Offer #"+u64(id)+" expired at height "+strconv.FormatInt(o.Expiry, 10)+".")
		}
		offs[i] = o
		legs[i] = ring.Leg{Offer: o.ID, Owner: o.Owner, Give: o.Give, Want: o.Want}
	}

	canonicalIDs := ring.FormatOfferIDs(idList)
	var sb strings.Builder
	sb.WriteString("# Ring: " + canonicalIDs + "\n\n")
	sb.WriteString(navBar("") + "\n\n")

	if len(problems) > 0 {
		sb.WriteString("> [!WARNING] Cannot settle this ring\n")
		for _, p := range problems {
			sb.WriteString("> - " + sanitize.InlineText(p) + "\n")
		}
		sb.WriteString("\n[Back to Kylix](" + webPath() + ")\n")
		return sb.String()
	}

	hops, err := ring.VerifyWithBridge(legs)
	if err != nil {
		sb.WriteString("> [!WARNING] Not a valid ring\n> " + sanitize.InlineText(plainSwapReason(err.Error())) + "\n\n")
		sb.WriteString("[Back to Kylix](" + webPath() + ")\n")
		return sb.String()
	}

	// Live readiness check (same checks SettleRing runs before moving anything).
	reasons := make([]string, len(idList))
	var bridgeFeeTier uint32
	bridgeHasPool := true
	allReady := true
	hasBridge := false

	for i, o := range offs {
		reasons[i] = undeliverable(o)
		if reasons[i] != "" {
			allReady = false
		}
		if hops[i].Bridged {
			hasBridge = true
			fee, ok := bridgeFee(hops[i].Asset.Key, hops[i].Want.Key)
			bridgeFeeTier, bridgeHasPool = fee, ok
			if !ok {
				allReady = false
			}
		}
	}

	// Large ring graph.
	graphHops := make([]ring.GraphHop, n)
	for i, h := range hops {
		gh := ring.GraphHop{
			From:    ownerPlain(offs[i].Owner, cache),
			Give:    graphAsset(h.Asset),
			Note:    svgHint(assetHint(h.Asset)),
			OfferID: offs[i].ID,
			Bridged: h.Bridged,
		}
		if h.Bridged {
			gh.Want = "≥ " + graphAsset(h.Want)
			gh.WantNote = svgHint(assetHint(h.Want))
		}
		graphHops[i] = gh
	}
	if uri := ring.GraphDataURI(graphHops, ring.GraphFull); uri != "" {
		sb.WriteString("![Ring " + canonicalIDs + "](" + uri + ")\n\n")
	}

	// Status banner & primary settle button.
	variant := "outline"
	if allReady {
		variant = "success"
		sb.WriteString("> [!SUCCESS] Ready to settle\n> Every owner holds their asset and has approved this swap")
		if hasBridge {
			sb.WriteString(", and a GnoSwap pool (" + formatFeePercent(bridgeFeeTier) + " fee tier) is available for the swap through GnoSwap")
		}
		sb.WriteString(". Anyone can settle this ring in one transaction.\n\n")
	} else {
		sb.WriteString("> [!WARNING] Not ready to settle right now\n> One or more swaps cannot deliver yet (see table below). ")
		sb.WriteString("Nothing will move until every swap is ready.\n\n")
	}
	if hasBridge && bridgeHasPool {
		// Name the pool: the automatic choice can be steered by whoever adds
		// liquidity to another pool of the same pair.
		sb.WriteString(gnoButton(txLink(webPath(), "SettleRingVia", "ids", canonicalIDs, "fee", strconv.FormatUint(uint64(bridgeFeeTier), 10)),
			"Settle through the "+formatFeePercent(bridgeFeeTier)+" pool", variant) + "\n\n")
		sb.WriteString("The " + formatFeePercent(bridgeFeeTier) + " pool is the one holding the most of the token being bought. " +
			"If GnoSwap has several pools for this pair, check which one gives the best price before settling, and pick it in the form at the bottom of this page.\n\n")
	} else {
		sb.WriteString(gnoButton(txLink(webPath(), "SettleRing", "ids", canonicalIDs), "Settle this ring", variant) + "\n\n")
	}

	// Swaps spelled out in plain words.
	sb.WriteString("## Swaps in this ring\n\n")
	for i, h := range hops {
		from := offs[h.From]
		to := offs[h.To]
		sb.WriteString(strconv.Itoa(i+1) + ". " + ownerMarkdown(from.Owner, cache) + " gives " +
			keyedAsset(h.Asset, false) + " ")
		if h.Bridged {
			sb.WriteString("→ swapped on **GnoSwap**")
			if bridgeHasPool {
				sb.WriteString(" (" + formatFeePercent(bridgeFeeTier) + " pool)")
			} else {
				sb.WriteString(" (no pool found)")
			}
			sb.WriteString(" → " + keyedAsset(h.Want, true) + " to " +
				ownerMarkdown(to.Owner, cache))
		} else {
			sb.WriteString("to " + ownerMarkdown(to.Owner, cache))
			if h.Asset.Kind == ring.Fungible && h.Asset.Amount > h.Want.Amount {
				sb.WriteString(" (asked for at least " + sanitize.InlineText(graphAsset(h.Want)) + "; keeps the full amount)")
			}
		}
		sb.WriteString(" — [offer #" + u64(from.ID) + "](" + webPath() + ":offer/" + u64(from.ID) + ")\n")
	}

	// Deliverability table.
	sb.WriteString("\n## Is every swap ready?\n\n")
	sb.WriteString("| Swap | Offer | Owner | Gives | Ready now? |\n|---|---|---|---|---|\n")
	for i, o := range offs {
		status := "Ready"
		if reasons[i] != "" {
			status = "Not ready: " + sanitize.TableCell(plainSwapReason(reasons[i]))
		} else if hops[i].Bridged && !bridgeHasPool {
			status = "No GnoSwap pool for this pair"
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | [#" + u64(o.ID) + "](" + webPath() + ":offer/" + u64(o.ID) + ") | " +
			ownerTableCell(o.Owner, cache) + " | " + sanitize.TableCell(shortAsset(o.Give)) + " | " + status + " |\n")
	}

	// CLI fallback form.
	sb.WriteString("\n## Settle with gnokey\n\n")
	gasWanted := settleGasWanted(offs, hasBridge)
	sb.WriteString("Wallet users can click the settle button above. From the command line, set a deposit limit: settling runs each collection's code, and any storage it adds is charged to you. ")
	sb.WriteString("The gas limit below is sized to this ring (what such rings measured, with headroom) and the fee is the minimum for it at the base gas price (1 ugnot per 1,000 gas), because the whole fee is paid whatever gas is used. If the simulation runs out of gas, raise both together; nothing is charged for a failed simulation. The storage the ring frees is refunded to you.\n\n")
	fn, extra := "SettleRing", ""
	if hasBridge && bridgeHasPool {
		fn, extra = "SettleRingVia", " -args "+strconv.FormatUint(uint64(bridgeFeeTier), 10)
	}
	sb.WriteString("```\ngnokey maketx call -pkgpath " + selfPath + " -func " + fn + " -args " + canonicalIDs + extra +
		" \\\n  -gas-fee " + strconv.FormatInt(gasWanted/1000, 10) + "ugnot -gas-wanted " + strconv.FormatInt(gasWanted, 10) + " -max-deposit 500000ugnot \\\n  -broadcast -chainid " +
		runtime.ChainID() + " -remote <rpc address> <your key>\n```\n\n")
	sb.WriteString("Or submit the form below to generate a command:\n\n")
	if hasBridge {
		sb.WriteString("<gno-form exec=\"SettleRingVia\">\n")
		sb.WriteString(gnoInput("ids", "Offer IDs in ring order", canonicalIDs, true, true))
		for i, f := range feeTiers {
			desc := ""
			if i == 0 {
				desc = "GnoSwap pool to swap through (fee tier)"
			}
			sb.WriteString(gnoSelectOpt("fee", strconv.FormatUint(uint64(f), 10), desc, f == bridgeFeeTier, i == 0))
		}
		sb.WriteString("</gno-form>\n")
	} else {
		sb.WriteString("<gno-form exec=\"SettleRing\">\n")
		sb.WriteString(gnoInput("ids", "Offer IDs in ring order", canonicalIDs, true, true))
		sb.WriteString("</gno-form>\n")
	}

	return sb.String()
}

// settleGasWanted sizes a settle command's gas limit to the ring: 25M, plus
// 5M per token offer, 14M per MNS name (the adapter reads the registry), 8M
// per other item, and 50M for a GnoSwap hop. Measured on a local chain
// (gno v1.8.0): 2 token offers used 24 to 29M gas, a token and a relic 30M,
// a token and an MNS name 37M, 6 token offers 39M, 3 relics and 3 tokens
// 59M, 6 items 52 to 60M (6 Sinopia3 tokens 53M in a filetest); a real
// GnoSwap swap alone used about 34M. Third-party collection code may use
// more; the simulation then fails without charging a fee. The solver is
// meant to print the same limits.
func settleGasWanted(offs []*Offer, bridged bool) int64 {
	g := int64(25_000_000)
	mns := namespacePrefix() + "adapters/nsnft"
	for _, o := range offs {
		switch {
		case o.Give.Kind != ring.Item:
			g += 5_000_000
		case o.Give.Key == mns:
			g += 14_000_000
		default:
			g += 8_000_000
		}
	}
	if bridged {
		g += 50_000_000
	}
	return g
}

// renderPost renders the offer-posting workflow:
//  1. An interactive builder (<gno-form path="post">) that computes the user's
//     exact approve address via NextSlot / ApproveTarget and produces prefilled
//     GnoConnect / $help transaction buttons for both Approve and PostIntent.
//  2. A direct <gno-form exec="PostIntent"> fallback for gnokey users.
func renderPost(rawQuery string) string {
	// Parse and strictly allowlist any query params returned by the builder form.
	q, _ := url.ParseQuery(rawQuery)
	ownerAddr, ownerErr := resolveOwnerInput(q.Get("owner"))
	giveKind := parseKindChoice(q.Get("giveKind"))
	giveKey := allowAssetKey(q.Get("giveKey"))
	giveID := cleanItemIDInput(q.Get("giveID"))
	giveAmount := parseNonNegInt64(q.Get("giveAmount"))
	wantKind := parseKindChoice(q.Get("wantKind"))
	wantKey := allowAssetKey(q.Get("wantKey"))
	tokens, colls := knownAssets(giveKey, wantKey)
	wantID := cleanItemIDInput(q.Get("wantID"))
	wantMin := parseNonNegInt64(q.Get("wantMin"))
	expiry := parseNonNegInt64(q.Get("expiry"))

	// Infer kind from chosen key when the user selected a known asset.
	if giveKey != "" {
		if IsCollection(giveKey) {
			giveKind = "item"
		} else if tokenOf(giveKey) != nil {
			giveKind = "fungible"
		}
	}
	if wantKey != "" {
		if IsCollection(wantKey) {
			wantKind = "item"
		} else if tokenOf(wantKey) != nil {
			wantKind = "fungible"
		}
	}

	var sb strings.Builder
	sb.WriteString("# Post an offer\n\n")
	sb.WriteString(navBar("post") + "\n\n")
	sb.WriteString("Kylix never holds your assets. Posting an offer takes two steps: **approve** your offer's own address, then **post** the offer. ")
	sb.WriteString("When you post, Kylix checks that a token offer, or an item of an official collection, could settle right now. It runs no third-party collection's code when you post: such an item is checked only when someone settles.\n\n")
	sb.WriteString("> [!NOTE] Your minimum is your price\n> If what you receive comes through a GnoSwap swap, expect to receive exactly the minimum you ask for, not more: " +
		"anyone can trade on the same pool around the swap and keep the difference. Set your minimum to the amount you actually want. " +
		"Your offer stays open until it settles, you cancel it, or it expires (about 7 days by default, at most about 30).\n\n")

	// If the builder form was submitted, show tailored Approve + Post transaction buttons.
	hasDraft := len(q) > 0
	if hasDraft {
		writeDraftSummary(&sb, ownerAddr, ownerErr, giveKind, giveKey, giveID, giveAmount, wantKind, wantKey, wantID, wantMin, expiry)
	}

	sb.WriteString("## Step 1: Prepare your offer (wallet & approve helper)\n\n")
	sb.WriteString("Pick what you give and what you want below. Adding your address or `@username` lets Kylix calculate the exact address to approve for your next offer.\n\n")
	sb.WriteString("<gno-form path=\"post\">\n")
	ownerVal := ""
	if ownerAddr != "" {
		ownerVal = ownerAddr.String()
	}
	sb.WriteString(gnoInput("owner", "Your g1 address or @username (optional, to compute approve address)", ownerVal, false, false))
	writeKindSelect(&sb, "giveKind", "What are you giving?", giveKind, false)
	writeAssetSelect(&sb, "giveKey", "Token or collection you give", giveKey, tokens, colls, false)
	sb.WriteString(gnoInput("giveID", "Item ID you give (leave blank for tokens)", giveID, false, false))
	sb.WriteString(gnoInput("giveAmount", "Token amount you give (0 for items)", formatIntOrEmpty(giveAmount), false, false))
	writeKindSelect(&sb, "wantKind", "What do you want back?", wantKind, false)
	writeAssetSelect(&sb, "wantKey", "Token or collection you want", wantKey, tokens, colls, false)
	sb.WriteString(gnoInput("wantID", "Item ID you want (leave blank for tokens)", wantID, false, false))
	sb.WriteString(gnoInput("wantMin", "Minimum token amount you want (0 for items)", formatIntOrEmpty(wantMin), false, false))
	sb.WriteString(gnoInput("expiry", expiryInputHint(), formatIntOrEmpty(expiry), false, false))
	sb.WriteString("</gno-form>\n\n")

	sb.WriteString("## Step 2: Approve your swap address\n\n")
	sb.WriteString("Every offer you post gets its own address, computed from your address and how many offers you have posted (`NextSlot`). ")
	sb.WriteString("Before your offer can settle, approve that address for the exact token amount or item, or, for a collection that trades through an adapter, the adapter's address for your offer (`ApproveTarget`).\n\n")
	sb.WriteString(gnoButton(txLink(webPath(), "NextSlot"), "Look up NextSlot ($help)", "outline") + " ")
	sb.WriteString(gnoButton(txLink(webPath(), "ApproveTarget"), "Look up ApproveTarget ($help)", "outline") + " ")
	sb.WriteString(gnoButton(demoWebPath(), "Need test assets? Demo faucet", "outline") + "\n\n")

	sb.WriteString("## Direct gnokey form\n\n")
	sb.WriteString("Prefer to copy a `gnokey` command directly? Fill in the fields below, or ")
	sb.WriteString(gnoButton(txLink(webPath(), "PostIntent"), "Open post call in wallet / $help", "info") + ".\n\n")

	sb.WriteString("<gno-form exec=\"PostIntent\">\n")
	writeKindSelect(&sb, "giveKind", "Give kind (fungible or item)", giveKind, true)
	writeAssetSelect(&sb, "giveKey", "Give token or collection key", giveKey, tokens, colls, true)
	sb.WriteString(gnoInput("giveID", "Give item ID (empty for tokens)", giveID, false, false))
	sb.WriteString(gnoInput("giveAmount", "Give amount (0 for items)", strconv.FormatInt(giveAmount, 10), true, false))
	writeKindSelect(&sb, "wantKind", "Want kind (fungible or item)", wantKind, true)
	writeAssetSelect(&sb, "wantKey", "Want token or collection key", wantKey, tokens, colls, true)
	sb.WriteString(gnoInput("wantID", "Want item ID (empty for tokens)", wantID, false, false))
	sb.WriteString(gnoInput("wantMin", "Minimum wanted amount (0 for items)", strconv.FormatInt(wantMin, 10), true, false))
	sb.WriteString(gnoInput("expiry", expiryInputHint(), strconv.FormatInt(expiry, 10), true, false))
	sb.WriteString("</gno-form>\n")

	return sb.String()
}

func writeDraftSummary(sb *strings.Builder, owner address, ownerErr string,
	giveKind, giveKey, giveID string, giveAmount int64,
	wantKind, wantKey, wantID string, wantMin, expiry int64,
) {
	sb.WriteString("<gno-frame>\n### Your prepared offer\n\n")
	if ownerErr != "" {
		sb.WriteString("> [!WARNING] Address not recognized\n> " + sanitize.InlineText(ownerErr) + "\n\n")
	}

	var errs []string
	give, gErr := checkDraftAsset("give", giveKind, giveKey, giveID, giveAmount)
	if gErr != "" {
		errs = append(errs, gErr)
	}
	want, wErr := checkDraftAsset("want", wantKind, wantKey, wantID, wantMin)
	if wErr != "" {
		errs = append(errs, wErr)
	}
	if gErr == "" && wErr == "" && give.SameAs(want) {
		errs = append(errs, "An offer cannot give the exact asset it wants.")
	}
	if h := runtime.ChainHeight(); expiry != 0 && expiry <= h {
		errs = append(errs, "The expiry must be a future block height (the current height is "+strconv.FormatInt(h, 10)+"), or 0 for the default of about 7 days.")
	} else if expiry > h+MaxExpiryBlocks {
		errs = append(errs, "The expiry can be at most about 30 days ahead: block height "+strconv.FormatInt(h+MaxExpiryBlocks, 10)+" or lower.")
	}

	if owner != "" {
		nonce, slot := NextSlot(owner)
		target := slot
		if giveKey != "" {
			target = ApproveTarget(owner, nonce, giveKey)
		}
		sb.WriteString("> [!CAUTION] Prepared for account `" + owner.String() + "`\n")
		sb.WriteString("> The addresses below are computed for this account. If it is not yours, do not approve or post: this page was prepared for someone else.\n\n")
		sb.WriteString("**1. Approve this address first** (it belongs to offer number " + u64(nonce) + " of `" + owner.String() + "`):\n\n")
		sb.WriteString("- Approve address: `" + target.String() + "`\n")
		if target != slot {
			sb.WriteString("- Your offer's own address: `" + slot.String() + "` (this collection trades through an adapter, so approve the address above, not this one)\n")
		}
		sb.WriteString("\n")
		if gErr == "" {
			writeApproveInstructions(sb, give, target, slot)
			sb.WriteString("\n")
		}
	}

	if len(errs) > 0 {
		sb.WriteString("> [!NOTE] Finish the offer fields to generate the Post button\n")
		for _, e := range errs {
			sb.WriteString("> - " + sanitize.InlineText(e) + "\n")
		}
		sb.WriteString("</gno-frame>\n\n")
		return
	}

	sb.WriteString("**2. Post your offer:** giving " + keyedAsset(give, false) + " for " + keyedAsset(want, true))
	if expiry != 0 {
		sb.WriteString(" (expires " + blocksAhead(expiry-runtime.ChainHeight()) + ", at block height " + strconv.FormatInt(expiry, 10) + ")")
	} else {
		sb.WriteString(" (expires in about 7 days)")
	}
	sb.WriteString(".\n\n")
	sb.WriteString("Check the keys in code before you sign: anyone can deploy a token or collection with the same symbol or name as a well-known one, and the key is what the offer is for.\n\n")

	postURL := txLink(webPath(), "PostIntent",
		"giveKind", giveKind,
		"giveKey", giveKey,
		"giveID", giveID,
		"giveAmount", strconv.FormatInt(giveAmount, 10),
		"wantKind", wantKind,
		"wantKey", wantKey,
		"wantID", wantID,
		"wantMin", strconv.FormatInt(wantMin, 10),
		"expiry", strconv.FormatInt(expiry, 10),
	)
	sb.WriteString(gnoButton(postURL, "Post offer (wallet / $help)", "success") + "\n")
	sb.WriteString("</gno-frame>\n\n")
}

func checkDraftAsset(side, kind, key, id string, amount int64) (ring.Asset, string) {
	k, ok := ring.ParseKind(kind)
	if !ok {
		return ring.Asset{}, "Choose whether you " + side + " a fungible token or an item."
	}
	if key == "" {
		return ring.Asset{}, "Choose the token or collection you " + side + "."
	}
	a := ring.Asset{Kind: k, Key: key, ID: id, Amount: amount}
	switch k {
	case ring.Fungible:
		if tokenOf(key) == nil {
			return ring.Asset{}, "The selected " + side + " key is not a registered token."
		}
		if id != "" {
			return ring.Asset{}, "Leave the " + side + " item ID blank for tokens."
		}
		if amount <= 0 {
			return ring.Asset{}, "Enter a positive " + side + " token amount."
		}
	case ring.Item:
		if !IsCollection(key) {
			return ring.Asset{}, "The selected " + side + " key is not a registered collection."
		}
		if !validItemID(id) {
			return ring.Asset{}, "Enter a valid " + side + " item ID (1–64 chars: A-Z, a-z, 0-9, . _ : / - *)."
		}
		if amount != 0 {
			return ring.Asset{}, "Set " + side + " amount to 0 for an item."
		}
	}
	return a, ""
}

// renderCollections renders the registered collections with their trust
// labels, official ones first, pageCollections per page; after is the last
// key of the previous page.
func renderCollections(after string) string {
	var sb strings.Builder
	sb.WriteString("# Registered collections\n\n")
	sb.WriteString(navBar("collections") + "\n\n")
	sb.WriteString("Items from any collection listed here can be traded in Kylix rings. Anyone can register a collection, under any display name, so every collection carries one of these labels:\n\n")
	sb.WriteString("- **Official collection:** registered from Kylix's own namespace (`" + namespacePrefix() + "`), built directly for Kylix. You approve your offer's own address in the collection itself.\n")
	sb.WriteString("- **Official adapter:** maintained under Kylix's own namespace for an existing collection. You approve the adapter's per-offer address (`ApproveTarget`).\n")
	sb.WriteString("- **Third-party collection** or **third-party adapter:** registered by someone else under their own namespace. **What this means for you:** its name can copy an official one's, and its code is not Kylix's. Kylix always checks that the item's owner changed after a swap, but read the code before offering or asking for its items, and check the key, not the name.\n\n")

	if collections.Size() == 0 {
		sb.WriteString("No collections are registered yet.\n\n")
	} else {
		keys, more := collectionKeys(after, pageCollections)
		sb.WriteString(strconv.Itoa(collections.Size()) + " registered, official ones first.\n\n")
		sb.WriteString("| Collection | Label | Collection / Adapter key | Target realm | Approval check |\n")
		sb.WriteString("|---|---|---|---|---|\n")
		for _, key := range keys {
			c := getCollection(key)
			target := "—"
			if c.target != "" {
				target = "[" + sanitize.TableCell(c.target) + "](" + pkgWebPath(c.target) + ")"
			}
			check := "No"
			if c.approved != nil {
				check = "Yes"
			}
			sb.WriteString("| **" + sanitize.TableCell(c.name) + "** | " + collectionKind(key) + " | [" +
				sanitize.TableCell(key) + "](" + pkgWebPath(key) + ") | " + target + " | " + check + " |\n")
		}
		if more {
			sb.WriteString("\n[More collections →](" + webPath() + ":collections?after=" + url.QueryEscape(keys[len(keys)-1]) + ")\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("Want to make your own collection tradable on Kylix? See the [plug-in guide](" + webPath() + ":about#plug-in-your-collection).\n")
	return sb.String()
}

// renderAbout explains how Kylix works, custody guarantees, GnoSwap fees,
// what settling costs, and how collection authors plug in.
func renderAbout() string {
	var sb strings.Builder
	sb.WriteString("# How Kylix works\n\n")
	sb.WriteString(navBar("about") + "\n\n")

	sb.WriteString("Kylix is named after the Greek drinking cup passed round the circle at a banquet. ")
	sb.WriteString("Instead of matching only two people who want each other's exact asset, Kylix lets 2 to 6 offers form a closed circle and settles every swap at once.\n\n")
	sb.WriteString("For example: Alice offers **100 OBOL** and wants **50 DRACHMA**; Bob offers **Relic #2** and wants **100 OBOL**; Carol offers **50 DRACHMA** and wants **Relic #2**. ")
	sb.WriteString("No two of them can trade directly, yet passing each asset one step round the circle satisfies everyone in a single transaction.\n\n")

	sb.WriteString("## How settlement works\n\n")
	sb.WriteString("1. **Approve one dedicated address.** Each offer gets its own address (`NextSlot`, or `ApproveTarget` for collections that trade through an adapter). You allow only that address to move only the asset you are offering.\n")
	sb.WriteString("2. **Post your offer.** State what you give and the minimum you want back. Approve first: Kylix accepts an offer of a token, or of an item of an official collection, only if it could settle right now, so you must hold what you offer and have approved it. An item of a third-party collection is not checked when you post, so that collection's code never runs at your expense; it is checked when someone settles. Nothing leaves your wallet when you post. ")
	sb.WriteString("Every offer has an end date: about 7 days unless you choose another block height, and at most about 30 days.\n")
	sb.WriteString("3. **Anyone settles the ring.** When 2 to 6 open offers close a ring, anyone (a trader, a visitor on this page, or a program that searches for rings) can settle it with `SettleRing`.\n")
	sb.WriteString("4. **All or nothing.** Kylix checks that every offer is open, not expired and ready, removes the offers from the book, and moves every asset straight from each owner to the next. If any single swap fails, the whole transaction is undone and nothing moves.\n\n")

	sb.WriteString("## Check the key, not the name\n\n")
	sb.WriteString("Anyone can deploy a token whose symbol is GNS or OBOL, or register a collection called Kylix Relics. ")
	sb.WriteString("So Kylix shows next to every asset the realm it lives in (for example `g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/kylixdemo`), and, where you decide to approve, post or settle, its full key. ")
	sb.WriteString("Collections registered from Kylix's own namespace are labelled **official**; every other one is **third-party**, whatever its name says.\n\n")
	sb.WriteString("## Approve exactly the amount you offer\n\n")
	sb.WriteString("A token offer settles only if its address may spend exactly the amount offered, not more. ")
	sb.WriteString("The approval is then used up when the ring settles, and the token realm frees it; a larger approval would stay behind, and the person settling would pay to store each receiver's new balance with nothing freed in return.\n\n")
	sb.WriteString("## What Kylix can and cannot do with your assets\n\n")
	sb.WriteString("<gno-columns>\n<gno-frame>\n### What Kylix can do\n")
	sb.WriteString("- Move **only** the token amount or item you offered, through an approval for exactly that, for a single offer.\n")
	sb.WriteString("- Move it **only** when a closed ring gives you at least the minimum you asked for.\n")
	sb.WriteString("- Return each offer's storage deposit to whoever removes it: you when you cancel, the settler when it settles, anyone once it has expired.\n")
	sb.WriteString("</gno-frame>\n<gno-columns-sep />\n<gno-frame>\n### What Kylix cannot do\n")
	sb.WriteString("- Hold your tokens or collectibles between swaps (no custody, no escrow vault).\n")
	sb.WriteString("- Reuse one offer's approval for any other offer or any other owner.\n")
	sb.WriteString("- Stop you from cancelling: cancelling calls no other realm.\n")
	sb.WriteString("- Accept native GNOT directly: trade GNOT as wrapped `wugnot` instead.\n")
	sb.WriteString("</gno-frame>\n</gno-columns>\n\n")

	sb.WriteString("## Swaps through GnoSwap\n\n")
	sb.WriteString("When a ring has one gap where someone gives token A and the next person wants a different token B, Kylix can fill that gap with a swap on **GnoSwap**, inside the same transaction.\n\n")
	sb.WriteString("> [!WARNING] Your minimum is your price\n")
	sb.WriteString("> When what you receive comes through a GnoSwap swap, expect to receive exactly the minimum you asked for, not more. ")
	sb.WriteString("Anyone can trade on the same pool in the same transaction, just before and after the swap, and keep any difference above your minimum. ")
	sb.WriteString("Set your minimum to the amount you actually want.\n\n")
	sb.WriteString("- **Kylix fee:** none.\n")
	sb.WriteString("- **GnoSwap pool fee:** 0.01%, 0.05%, 0.3% or 1%, depending on the pool.\n")
	sb.WriteString("- **GnoSwap router fee:** 0.15% of what the swap returns.\n")
	sb.WriteString("- **Which pool:** the person settling chooses it (`SettleRingVia`). `SettleRing` picks the pool holding the most of the token being bought, which works when a pair has one pool; with several, anyone can add liquidity that makes it pick a pool that cannot pay, and settling then fails until someone names a better pool.\n")
	sb.WriteString("- **Minimum protection:** if the swap returns less than the receiver's minimum after fees, nothing in the ring moves.\n\n")

	sb.WriteString("## What settling costs\n\n")
	sb.WriteString("Settling a ring that includes collectibles runs code written by each of those collections. That code can store data in its own realm, ")
	sb.WriteString("and the chain charges the storage deposit to whoever sends the transaction; a dishonest collection can collect that deposit later. ")
	sb.WriteString("If you settle rings, set a tight deposit limit (`-max-deposit` in gnokey) and be careful with **third-party** collections and adapters. ")
	sb.WriteString("Posting, cancelling and removing an expired offer never run third-party collection code, and neither does any page except a third-party item's own offer and ring pages: only settling does, and only the settler pays for it.\n\n")

	sb.WriteString("## Notifications\n\n")
	sb.WriteString("Kylix announces every settled offer to its owner (`OfferSettled`). ")
	sb.WriteString("You can opt in to browser alerts for your address on [gnotif](https://gnotif.xyz).\n\n")

	sb.WriteString("## Plug in your collection\n\n")
	sb.WriteString("> [!CAUTION] An item id must fix the item's value\n")
	sb.WriteString("> Between posting and settlement, the owner keeps the item. If anything that gives the item its value can change while its id stays the same, ")
	sb.WriteString("such as contents that can be withdrawn, an unrevealed picture, or a lease the owner can shorten, a buyer can pay for one thing and receive another. ")
	sb.WriteString("Such items must not be offered: put everything that decides the value into the id, or have your approval check answer no while the value can still change.\n\n")
	sb.WriteString("> [!CAUTION] An approval Kylix uses must be consumed by the move\n")
	sb.WriteString("> Accept only an approval of this one item, for exactly the address Kylix asks for, in both your approval check and your move, and make sure the transfer clears it. ")
	sb.WriteString("Do not accept an approval for all items (`SetApprovalForAll`): the transfer leaves it in place, so its storage deposit never comes back to whoever settles, while they pay for the receivers' new entries.\n\n")
	sb.WriteString("Any GRC721 or custom item realm can join Kylix in a few lines. Kylix calls your `Move` function crossing as the offer's own address, and checks `OwnerOf` afterwards:\n\n")
	sb.WriteString("```go\n")
	sb.WriteString("import \"" + selfPath + "\"\n\n")
	sb.WriteString("func init(cur realm) {\n")
	sb.WriteString("\tkylix.RegisterItem(cross(cur), \"My Collection\", MoveForKylix, OwnerForKylix)\n")
	sb.WriteString("\tkylix.RegisterApprovalCheck(cross(cur), ApprovedForKylix) // optional\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func MoveForKylix(cur realm, from, to address, itemID string) error {\n")
	sb.WriteString("\t// cur.Previous().Address() is the offer's address that `from` approved.\n")
	sb.WriteString("\t// Use only an approval of this one item: the transfer clears it.\n")
	sb.WriteString("\tif a, _ := token.GetApproved(grc721.TokenID(itemID)); a != cur.Previous().Address() {\n")
	sb.WriteString("\t\treturn errors.New(\"approve this offer's address for the item itself\")\n")
	sb.WriteString("\t}\n")
	sb.WriteString("\treturn ledger.CallerTeller().TransferFrom(0, cur, from, to, grc721.TokenID(itemID))\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func OwnerForKylix(id kylix.ItemID) address {\n")
	sb.WriteString("\towner, _ := token.OwnerOf(grc721.TokenID(id))\n")
	sb.WriteString("\treturn owner\n")
	sb.WriteString("}\n\n")
	sb.WriteString("func ApprovedForKylix(id kylix.ItemID, spender address) bool {\n")
	sb.WriteString("\tapproved, _ := token.GetApproved(grc721.TokenID(id))\n")
	sb.WriteString("\treturn approved != \"\" && approved == spender // not IsApprovedForAll\n")
	sb.WriteString("}\n")
	sb.WriteString("```\n\n")
	sb.WriteString("`OwnerForKylix` and `ApprovedForKylix` must not panic and should not store anything: return the empty address or false for an id you do not know. ")
	sb.WriteString("Kylix calls them when a ring with your item is settled, and on that offer's and ring's own pages; posting, cancelling and the home page never call a third-party collection. (Official collections, Kylix's own, are also checked at posting and on the home page.) ")
	sb.WriteString("For an already-deployed collection that cannot be changed, deploy a small adapter realm that calls `kylix.RegisterAdapter` and crosses into the target collection as `cur.Sub(\"k/\" + cur.Previous().Address().String())`.\n")
	return sb.String()
}

// pinnedTokens are listed first in the post page's token dropdowns, when
// registered: wrapped GNOT and GnoSwap's GNS. The demo tokens follow them.
var pinnedTokens = []string{"gno.land/r/gnoland/wugnot.wugnot", "gno.land/r/gnoswap/gns.GNS"}

// knownAssets lists the choices for the post page's dropdowns, at most
// maxFormAssetOpts tokens and maxFormAssetOpts collections. Anyone can
// register tokens and collections, so the useful ones come first and cannot
// be pushed out: tokens are wugnot, GNS, the demo realm's tokens, then the
// rest of grc20reg in key order; collections are the official ones, then
// the rest. Every key in selected that is registered is always included.
func knownAssets(selected ...string) (tokens []string, colls []string) {
	seenTok := map[string]bool{}
	addTok := func(key string) {
		if !seenTok[key] && tokenOf(key) != nil {
			seenTok[key] = true
			tokens = append(tokens, key)
		}
	}
	for _, k := range pinnedTokens {
		addTok(k)
	}
	reg := grc20reg.GetRegistry()
	if demo := demoRealmPath(); demo != "" && reg != nil {
		reg.Iterate(demo+".", demo+"/", func(key string, _ any) bool {
			if len(tokens) >= maxFormAssetOpts {
				return true
			}
			addTok(key)
			return false
		})
	}
	for _, k := range selected {
		addTok(k)
	}
	if reg != nil {
		reg.Iterate("", "", func(key string, _ any) bool {
			if len(tokens) >= maxFormAssetOpts {
				return true
			}
			addTok(key)
			return false
		})
	}

	seenColl := map[string]bool{}
	for _, k := range selected {
		if IsCollection(k) && IsOfficial(k) && !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	keys, _ := collectionKeys("", maxFormAssetOpts)
	for _, k := range keys {
		if len(colls) >= maxFormAssetOpts {
			break
		}
		if !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	for _, k := range selected {
		if IsCollection(k) && !seenColl[k] {
			seenColl[k] = true
			colls = append(colls, k)
		}
	}
	return tokens, colls
}

func writeKindSelect(sb *strings.Builder, name, desc, selected string, required bool) {
	sb.WriteString(gnoSelectOpt(name, "fungible", desc, selected == "" || selected == "fungible", required))
	sb.WriteString(gnoSelectOpt(name, "item", "", selected == "item", false))
}

func writeAssetSelect(sb *strings.Builder, name, desc, selected string, tokens, colls []string, required bool) {
	first := true
	addOpt := func(key string) {
		d := ""
		req := false
		if first {
			d = desc
			req = required
			first = false
		}
		sb.WriteString(gnoSelectOpt(name, key, d, key == selected, req))
	}
	for _, k := range tokens {
		addOpt(k)
	}
	for _, k := range colls {
		addOpt(k)
	}
	if first {
		// No registered assets yet; fall back to a plain input.
		sb.WriteString(gnoInput(name, desc, selected, required, false))
	}
}

func resolveOwnerInput(raw string) (address, string) {
	s := strings.TrimSpace(raw)
	if s == "" {
		return "", ""
	}
	s = strings.TrimPrefix(s, "@")
	if a := address(s); a.IsValid() {
		return a, ""
	}
	if u, _ := users.ResolveName(s); u != nil {
		return u.Addr(), ""
	}
	return "", "Enter a valid g1 address or a registered username."
}

func parseKindChoice(s string) string {
	switch strings.TrimSpace(s) {
	case "fungible":
		return "fungible"
	case "item":
		return "item"
	}
	return ""
}

// allowAssetKey accepts a key only if it is a registered token or
// collection, by direct lookup: no list of choices can crowd it out.
func allowAssetKey(raw string) string {
	s := strings.TrimSpace(raw)
	if s == "" || len(s) > 256 {
		return ""
	}
	if IsCollection(s) || tokenOf(s) != nil {
		return s
	}
	return ""
}

func cleanItemIDInput(raw string) string {
	s := strings.TrimSpace(raw)
	if validItemID(s) {
		return s
	}
	return ""
}

func parseNonNegInt64(raw string) int64 {
	s := strings.TrimSpace(raw)
	if s == "" {
		return 0
	}
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		return 0
	}
	return n
}

func formatIntOrEmpty(n int64) string {
	if n <= 0 {
		return ""
	}
	return strconv.FormatInt(n, 10)
}

func formatFeePercent(fee uint32) string {
	switch fee {
	case 100:
		return "0.01%"
	case 500:
		return "0.05%"
	case 3000:
		return "0.30%"
	case 10000:
		return "1.00%"
	}
	return strconv.FormatUint(uint64(fee), 10)
}

// plainSwapReason rewords internal p/ring error wording ("leg"/"legs") so
// user-facing pages speak consistently in terms of swaps and offers.
func plainSwapReason(s string) string {
	s = strings.ReplaceAll(s, " legs", " swaps")
	s = strings.ReplaceAll(s, "leg ", "swap ")
	return s
}

package kylix

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// SettleRing settles a ring of open offers. ids lists offer ids in ring
// order, comma-separated: the first offer's asset goes to the second offer's
// owner, and so on, and the last offer's asset goes to the first owner.
// Anyone may call it; the realm checks everything.
//
// A hop that gives one token where the receiver wants a different token is
// bridged by a GnoSwap swap (bridge.gno); a ring may contain one such hop.
// SettleRing picks the pool itself (see bridgeFee). That is a convenience:
// for a pair with several pools anyone can add liquidity that makes it pick
// a pool which cannot pay the receiver's minimum, and then the ring aborts.
// A settler who knows which pool to use calls SettleRingVia instead.
//
// Order of work:
//  1. Read and check: every offer is open and not expired, the ring is valid
//     (p/ring), every owner can deliver right now (balance and slot
//     allowance for a token; current ownership, and approval where the
//     collection registered a check, for an item), and a pool exists for a
//     bridged hop. This phase writes nothing to Kylix, and a failure names
//     the leg and offer at fault.
//  2. Take the re-entrancy lock and mark every offer settled by deleting it
//     from the book.
//  3. Move each leg's asset from its owner straight to the next owner, acting
//     as that offer's slot. After each item move, check that the next owner
//     really holds the item.
//
// If anything fails the transaction aborts and the chain rolls back every
// write, so the offers in the ring stay open and nothing has moved.
//
// SETTLERS PAY FOR COLLECTION CODE. For every item in the ring, phases 1 and
// 3 call that collection's registered functions. They run with their own
// realm's storage authority and may write to it, and the chain charges the
// transaction's sender the storage deposit for every realm whose storage
// grows. A hostile collection can therefore make settling its items cost up
// to the sender's deposit limit, and recover that deposit later. Settle with
// a tight -max-deposit, and be careful with third-party collections.
func SettleRing(cur realm, ids string) {
	settleRing(cur, ids, 0)
}

// SettleRingVia settles a ring like SettleRing, swapping its bridged hop
// through the GnoSwap pool with this fee tier (100, 500, 3000 or 10000,
// i.e. 0.01%, 0.05%, 0.3% or 1%). The pool must exist, and the ring must
// have a bridged hop. A solver chooses the pool off chain, for instance with
// the router's DrySwapRoute.
func SettleRingVia(cur realm, ids string, fee uint32) {
	if !isFeeTier(fee) {
		panic("kylix: fee must be one of GnoSwap's tiers: 100, 500, 3000 or 10000")
	}
	settleRing(cur, ids, fee)
}

// settleRing is SettleRing with an optional fee tier (0: choose).
func settleRing(cur realm, ids string, viaFee uint32) {
	guard(cur)
	idList, err := ring.ParseOfferIDs(ids)
	if err != nil {
		panic("kylix: " + err.Error())
	}

	height := runtime.ChainHeight()
	n := len(idList)
	offs := make([]*Offer, n)
	legs := make([]ring.Leg, n)
	for i, id := range idList {
		o := loadOffer(id)
		if o == nil {
			panic(legMsg(i, id, "offer is not open (unknown, settled, cancelled or pruned)"))
		}
		if expired(o, height) {
			panic(legMsg(i, id, "offer expired at height "+strconv.FormatInt(o.Expiry, 10)))
		}
		offs[i] = o
		legs[i] = ring.Leg{Offer: o.ID, Owner: o.Owner, Give: o.Give, Want: o.Want}
	}
	hops, err := ring.VerifyWithBridge(legs)
	if err != nil {
		panic("kylix: " + err.Error())
	}
	var fee uint32
	bridged := false
	for i, o := range offs {
		if why := undeliverable(o); why != "" {
			panic(legMsg(i, o.ID, why))
		}
		h := hops[i]
		if !h.Bridged {
			continue
		}
		bridged = true
		if viaFee != 0 {
			if !poolExists(h.Asset.Key, h.Want.Key, viaFee) {
				panic(legMsg(i, o.ID, "no GnoSwap pool with fee tier "+strconv.FormatUint(uint64(viaFee), 10)+
					" to swap "+h.Asset.Key+" for "+h.Want.Key))
			}
			fee = viaFee
			continue
		}
		var ok bool
		if fee, ok = bridgeFee(h.Asset.Key, h.Want.Key); !ok {
			panic(legMsg(i, o.ID, "no GnoSwap pool with reserves to swap "+h.Asset.Key+" for "+h.Want.Key))
		}
	}
	if viaFee != 0 && !bridged {
		panic("kylix: this ring has no swap through GnoSwap; use SettleRing")
	}

	locked = true
	for _, o := range offs {
		removeOffer(o.ID)
	}

	var bridgedGot int64
	for i, h := range hops {
		o := offs[i]
		slot := cur.Sub(slotPath(o.Owner, o.Nonce))
		to := offs[h.To].Owner
		if h.Bridged {
			settle := cur.Sub(settlePath)
			before := tokenOf(h.Want.Key).BalanceOf(to)
			bridgeHop(0, slot, settle, i, o, h, to, fee)
			bridgedGot = tokenOf(h.Want.Key).BalanceOf(to) - before
		} else {
			executeHop(0, slot, i, o, h, to)
		}
	}
	locked = false

	ringIDs := ring.FormatOfferIDs(idList)
	chain.Emit("RingSettled",
		"ids", ringIDs,
		"legs", strconv.Itoa(n),
		"settler", cur.Previous().Address().String(),
	)
	for i, o := range offs {
		in := (i + n - 1) % n
		received := hops[in].Asset.String()
		if hops[in].Bridged {
			received = ring.Asset{Kind: ring.Fungible, Key: hops[in].Want.Key, Amount: bridgedGot}.String()
		}
		chain.Emit(OfferSettledEvent,
			"owner", o.Owner.String(),
			"id", u64(o.ID),
			"ring", ringIDs,
			"gave", o.Give.String(),
			"received", received,
		)
	}
}

// executeHop moves one direct leg's asset. slot is the offer's own
// sub-realm token, minted from SettleRing's cur; it is never stored and
// never handed to foreign code except as the identity of a crossing call.
func executeHop(_ int, slot realm, i int, o *Offer, h ring.Hop, to address) {
	switch h.Asset.Kind {
	case ring.Fungible:
		// The slot is the spender, so only this offer's allowance can pay.
		grc20reg.TransferFrom(0, slot, h.Asset.Key, o.Owner, to, h.Asset.Amount)
	case ring.Item:
		c := getCollection(h.Asset.Key)
		if err := c.move(cross(slot), o.Owner, to, h.Asset.ID); err != nil {
			panic(legMsg(i, o.ID, "collection refused the move: "+err.Error()))
		}
		if got := c.ownerOf(ItemID(h.Asset.ID)); got != to {
			panic(legMsg(i, o.ID, "collection reported a move but item "+h.Asset.ID+" is owned by "+got.String()+", not "+to.String()))
		}
	default:
		panic(legMsg(i, o.ID, "unknown asset kind"))
	}
}

// undeliverable returns "" if o's owner could deliver o's asset right now,
// otherwise the reason not. It writes nothing to Kylix. For an item it calls
// the collection's OwnerFn and, if registered, its ApprovedFn; both run
// without crossing, so they cannot call back into Kylix's entry points, but
// they run with their own realm's storage authority and may write there, at
// the transaction sender's expense (see SettleRing). Without an ApprovedFn an
// item approval is only tested by the move itself.
func undeliverable(o *Offer) string {
	switch o.Give.Kind {
	case ring.Fungible:
		tok := tokenOf(o.Give.Key)
		if tok == nil {
			return "token is not in grc20reg"
		}
		need := o.Give.Amount
		if bal := tok.BalanceOf(o.Owner); bal < need {
			return "owner holds " + i64(bal) + " of " + o.Give.Key + ", offer gives " + i64(need)
		}
		// The allowance must equal the amount exactly. A larger one is not
		// used up, so the token realm keeps its entry and the settler, who
		// pays for every receiver's new balance entry, gets no refund for it.
		slot := SlotAddress(o.Owner, o.Nonce)
		if al := tok.Allowance(o.Owner, slot); al != need {
			return "slot " + slot.String() + " may spend " + i64(al) + " of " + o.Give.Key +
				"; approve exactly " + i64(need) + ", the amount this offer gives"
		}
	case ring.Item:
		c := getCollection(o.Give.Key)
		if c == nil {
			return "collection is not registered"
		}
		if got := c.ownerOf(ItemID(o.Give.ID)); got != o.Owner {
			return "owner no longer holds item " + o.Give.ID
		}
		if c.approved != nil {
			spender := ApproveTarget(o.Owner, o.Nonce, o.Give.Key)
			if !c.approved(ItemID(o.Give.ID), spender) {
				return "item " + o.Give.ID + " cannot be moved by " + spender.String() +
					" now (not approved, held by its collection, or refused by the collection's own rules)"
			}
		}
	default:
		return "unknown asset kind"
	}
	return ""
}

func tokenOf(key string) *grc20.Token { return grc20reg.Get(key) }

func legMsg(i int, id uint64, msg string) string {
	return "kylix: leg " + strconv.Itoa(i) + " (offer " + u64(id) + "): " + msg
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

package kylix

import (
	"strconv"
	"strings"

	"gno.land/p/nt/bptree/v0"
	"gno.land/p/g1muqflv3dsrrzsneg0eaz5jl7jaxzus0s4nm4x8/ring/v0"
)

// Storage layout.
//
// The chain charges the sender 100 ugnot per byte of realm storage, and a
// persisted struct costs far more than its contents: every object carries
// its own metadata and every field its type. An offer stored as an *Offer
// with two nested ring.Asset values in an avl.Tree took about 4.3 KB, or
// 0.43 GNOT, to post. So each open offer is stored as one string in a B+
// tree, and decoded into an Offer when read; that costs about 0.6-0.8 KB.
//
// The string is 12 fields joined by '|':
//
//	owner|nonce|giveKind|giveKey|giveID|giveAmount|wantKind|wantKey|wantID|wantMin|expiry|viaSession
//
// No field can contain '|': owners are bech32, keys are package paths or
// grc20reg keys, and item ids are validated by PostIntent. encodeOffer
// checks anyway.
var offers bptree.BPTree // offerKey(id) -> encoded offer, open offers only

const sep = "|"

func loadOffer(id uint64) *Offer {
	v := offers.Get(offerKey(id))
	if v == nil {
		return nil
	}
	return decodeOffer(id, v.(string))
}

func storeOffer(o *Offer) { offers.Set(offerKey(o.ID), encodeOffer(o)) }

// eachOfferAfter calls fn for every open offer with id > after, in id
// order, until fn returns true.
func eachOfferAfter(after uint64, fn func(o *Offer) bool) {
	if after == ^uint64(0) {
		return
	}
	start := ""
	if after > 0 {
		start = offerKey(after + 1)
	}
	offers.Iterate(start, "", func(k string, v any) bool { return fn(decodeOffer(parseOfferKey(k), v.(string))) })
}

// eachOfferBefore calls fn for every open offer with id < before (all when
// before is 0), newest first, until fn returns true.
func eachOfferBefore(before uint64, fn func(o *Offer) bool) {
	end := "" // ReverseIterate's end bound is inclusive
	switch {
	case before == 1:
		return
	case before > 1:
		end = offerKey(before - 1)
	}
	offers.ReverseIterate("", end, func(k string, v any) bool { return fn(decodeOffer(parseOfferKey(k), v.(string))) })
}

func encodeOffer(o *Offer) string {
	session := "0"
	if o.ViaSession {
		session = "1"
	}
	fields := []string{
		o.Owner.String(), u64(o.Nonce),
		kindDigit(o.Give.Kind), o.Give.Key, o.Give.ID, i64(o.Give.Amount),
		kindDigit(o.Want.Kind), o.Want.Key, o.Want.ID, i64(o.Want.Amount),
		i64(o.Expiry), session,
	}
	for _, f := range fields {
		if strings.Contains(f, sep) {
			panic("kylix: field contains the separator")
		}
	}
	return strings.Join(fields, sep)
}

// decodeOffer reverses encodeOffer in one pass. Pages decode every offer
// they show, so this is their main cost. In the GnoVM, ranging over a []byte
// costs about a quarter of indexing a string byte by byte, and far less than
// strings.Split followed by strconv parsing, so numbers are read as the scan
// passes them.
func decodeOffer(id uint64, s string) *Offer {
	var str [12]string // text fields
	var num [12]int64  // numeric fields
	field, start := 0, 0
	var n int64
	for i, c := range []byte(s) {
		if c == '|' {
			if field >= 11 {
				panic("kylix: corrupt offer record")
			}
			str[field], num[field] = s[start:i], n
			field, start, n = field+1, i+1, 0
		} else if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	if field != 11 {
		panic("kylix: corrupt offer record")
	}
	str[11], num[11] = s[start:], n
	// Numeric fields hold digits only (encodeOffer writes them with
	// strconv), so the running value above is exact for them.
	return &Offer{
		ID:         id,
		Owner:      address(str[0]),
		Nonce:      uint64(num[1]),
		Give:       ring.Asset{Kind: ring.Kind(num[2]), Key: str[3], ID: str[4], Amount: num[5]},
		Want:       ring.Asset{Kind: ring.Kind(num[6]), Key: str[7], ID: str[8], Amount: num[9]},
		Expiry:     num[10],
		ViaSession: str[11] == "1",
	}
}

// offerKey writes id in decimal behind a letter giving its length, so keys
// are short and still sort in numeric order: 7 -> "a7", 42 -> "b42".
func offerKey(id uint64) string {
	s := u64(id)
	return string(rune('a'+len(s)-1)) + s
}

func parseOfferKey(k string) uint64 { return mustU64(k[1:]) }

func kindDigit(k ring.Kind) string { return strconv.Itoa(int(k)) }

func mustU64(s string) uint64 {
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		panic("kylix: corrupt number in store")
	}
	return n
}

func mustI64(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("kylix: corrupt number in store")
	}
	return n
}

// Package escrowmath provides pure, deterministic milestone split math,
// quorum validation, Proof-of-Contribution XP scoring, and formatting helpers
// for OathLedger on Gno.land.
package escrowmath

import (
	"errors"
	"strconv"
	"strings"
)

const (
	BpsDenominator = int64(10000)
	MaxMilestones  = 10
	MaxReviewers   = 10
	UgnotPerGnot   = int64(1000000)
)

// ParseSplitsBps parses a comma-separated list of basis-point weights (e.g. "4000,3500,2500").
// Every milestone must be strictly positive and the weights must sum to exactly 10000 bps (100%).
func ParseSplitsBps(csv string) ([]int64, error) {
	trimmed := strings.TrimSpace(csv)
	if trimmed == "" {
		return nil, errors.New("splits cannot be empty")
	}

	parts := strings.Split(trimmed, ",")
	if len(parts) > MaxMilestones {
		return nil, errors.New("too many milestones (max 10)")
	}

	splits := make([]int64, len(parts))
	var total int64
	for i, raw := range parts {
		v, err := strconv.ParseInt(strings.TrimSpace(raw), 10, 64)
		if err != nil || v <= 0 {
			return nil, errors.New("each milestone split must be a positive integer in bps")
		}
		splits[i] = v
		total += v
	}

	if total != BpsDenominator {
		return nil, errors.New("milestone splits must sum to exactly 10000 bps")
	}
	return splits, nil
}

// ComputeMilestoneAmounts distributes totalUgnot deterministically across milestones.
// Any rounding remainder from integer division is assigned to the final milestone so
// sum(amounts) == totalUgnot holds as a strict conservation invariant (zero dust lost).
func ComputeMilestoneAmounts(totalUgnot int64, splitsBps []int64) ([]int64, error) {
	if totalUgnot <= 0 {
		return nil, errors.New("total escrow amount must be positive")
	}
	if len(splitsBps) == 0 || len(splitsBps) > MaxMilestones {
		return nil, errors.New("invalid milestone count")
	}

	var bpsSum int64
	for _, s := range splitsBps {
		if s <= 0 {
			return nil, errors.New("split weight must be positive")
		}
		bpsSum += s
	}
	if bpsSum != BpsDenominator {
		return nil, errors.New("splits must sum to 10000 bps")
	}

	amounts := make([]int64, len(splitsBps))
	var allocated int64
	for i := 0; i < len(splitsBps); i++ {
		if i == len(splitsBps)-1 {
			amounts[i] = totalUgnot - allocated
		} else {
			share := (totalUgnot * splitsBps[i]) / BpsDenominator
			amounts[i] = share
			allocated += share
		}
		if amounts[i] <= 0 {
			return nil, errors.New("escrow amount too small for milestone granularity")
		}
	}
	return amounts, nil
}

// ComputeDisputeSplit splits remainingUgnot between builder and sponsor using builderShareBps (0..10000).
func ComputeDisputeSplit(remainingUgnot, builderShareBps int64) (builderAmt int64, sponsorAmt int64, err error) {
	if remainingUgnot < 0 {
		return 0, 0, errors.New("remaining amount cannot be negative")
	}
	if builderShareBps < 0 || builderShareBps > BpsDenominator {
		return 0, 0, errors.New("builder share must be between 0 and 10000 bps")
	}
	builderAmt = (remainingUgnot * builderShareBps) / BpsDenominator
	sponsorAmt = remainingUgnot - builderAmt
	return builderAmt, sponsorAmt, nil
}

// ValidateQuorum checks that 1 <= quorum <= reviewerCount <= MaxReviewers.
func ValidateQuorum(quorum, reviewerCount int) error {
	if reviewerCount <= 0 || reviewerCount > MaxReviewers {
		return errors.New("reviewer count must be between 1 and 10")
	}
	if quorum <= 0 || quorum > reviewerCount {
		return errors.New("quorum must be between 1 and reviewer count")
	}
	return nil
}

// CalculatePoCXP computes deterministic Proof-of-Contribution XP for a paid milestone.
func CalculatePoCXP(ugnotEarned int64, onTime bool, cleanRecord bool) int64 {
	// Base 100 XP per verified milestone + 10 XP per GNOT earned (capped at +2000 XP/milestone)
	xp := int64(100)
	bonus := (ugnotEarned / UgnotPerGnot) * 10
	if bonus > 2000 {
		bonus = 2000
	}
	xp += bonus
	if onTime {
		xp += 50
	}
	if cleanRecord {
		xp += 25
	}
	return xp
}

// TierForXP maps cumulative Proof-of-Contribution XP into a readable builder badge tier.
func TierForXP(xp int64) string {
	switch {
	case xp >= 4000:
		return "Legend"
	case xp >= 1500:
		return "Master"
	case xp >= 500:
		return "Craftsman"
	default:
		return "Apprentice"
	}
}

// FormatGnot formats ugnot into a readable GNOT string (e.g. 1500000 -> "1.500000 GNOT").
func FormatGnot(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg = "-"
		ugnot = -ugnot
	}
	whole := ugnot / UgnotPerGnot
	frac := ugnot % UgnotPerGnot
	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	return neg + strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// ProgressBar renders a deterministic text progress bar for gnoweb Markdown views.
func ProgressBar(released, total int64, width int) string {
	if width <= 0 {
		width = 10
	}
	if total <= 0 {
		return "[" + strings.Repeat("-", width) + "] 0%"
	}
	pct := (released * 100) / total
	if pct > 100 {
		pct = 100
	}
	if pct < 0 {
		pct = 0
	}
	filled := int((pct * int64(width)) / 100)
	return "[" + strings.Repeat("#", filled) + strings.Repeat("-", width-filled) + "] " + strconv.FormatInt(pct, 10) + "%"
}

package escrowmath

import "testing"

func TestParseSplitsBps(t *testing.T) {
	splits, err := ParseSplitsBps("4000, 3500, 2500")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(splits) != 3 || splits[0] != 4000 || splits[1] != 3500 || splits[2] != 2500 {
		t.Fatalf("unexpected splits: %v", splits)
	}

	if _, err := ParseSplitsBps("5000,4000"); err == nil {
		t.Fatalf("expected error for sum != 10000")
	}
	if _, err := ParseSplitsBps("10000,0"); err == nil {
		t.Fatalf("expected error for zero split")
	}
}

func TestComputeMilestoneAmountsConservation(t *testing.T) {
	splits := []int64{3333, 3333, 3334}
	total := int64(1000001) // non-divisible amount to test zero-dust remainder conservation
	amts, err := ComputeMilestoneAmounts(total, splits)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	sum := amts[0] + amts[1] + amts[2]
	if sum != total {
		t.Fatalf("conservation violated: got %d, want %d", sum, total)
	}
}

func TestComputeDisputeSplit(t *testing.T) {
	b, s, err := ComputeDisputeSplit(5000000, 6000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if b != 3000000 || s != 2000000 {
		t.Fatalf("got (%d,%d), want (3000000,2000000)", b, s)
	}
	if _, _, err := ComputeDisputeSplit(1000, 10001); err == nil {
		t.Fatalf("expected error for bps > 10000")
	}
}

func TestFormatAndTiers(t *testing.T) {
	if got := FormatGnot(1250000); got != "1.250000 GNOT" {
		t.Fatalf("got %s", got)
	}
	if got := FormatGnot(500); got != "0.000500 GNOT" {
		t.Fatalf("got %s", got)
	}
	if got := TierForXP(100); got != "Apprentice" {
		t.Fatalf("got %s", got)
	}
	if got := TierForXP(1800); got != "Master" {
		t.Fatalf("got %s", got)
	}
	if got := ProgressBar(50, 100, 10); got != "[#####-----] 50%" {
		t.Fatalf("got %s", got)
	}
}

// Package oathledger implements OathLedger: a trustless, multi-milestone native GNOT
// escrow protocol with M-of-N peer-reviewer quorums, trustless quorum dispute resolution,
// deadline auto-refunds, and an immutable Proof-of-Contribution builder reputation ledger.
package oathledger

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strings"
	"time"

	"gno.land/p/g1ty0rp975ndkcse760v0zt659f4phs4z8lueud7/escrowmath"
	"gno.land/p/nt/avl/v0"
)

var (
	pacts               avl.Tree // padID(id) -> *Pact
	builders            avl.Tree // address.String() -> *BuilderProfile
	nextPactID          int64 = 1
	totalEscrowedUgnot  int64
	activeLockedUgnot   int64
	totalReleasedUgnot  int64
	completedPactsCount int64
	disputedPactsCount  int64
)

// CreatePact locks native ugnot from the sponsor into the realm with deterministic
// milestone splits and an M-of-N reviewer quorum.
//
// Security note: Only direct user calls (maketx call) are accepted so unsafe.OriginSend()
// accurately reflects real ugnot transferred to this realm (prevents phantom-send drains).
func CreatePact(
	cur realm,
	title string,
	summary string,
	milestoneTitlesCSV string,
	splitsBpsCSV string,
	reviewersCSV string,
	quorum int,
	deadlineHours int64,
) int64 {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}

	title = strings.TrimSpace(title)
	summary = strings.TrimSpace(summary)
	if title == "" || len(title) > 120 {
		panic("title must be 1..120 characters")
	}
	if summary == "" || len(summary) > 600 {
		panic("summary must be 1..600 characters")
	}
	if deadlineHours <= 0 || deadlineHours > 24*180 {
		panic("deadlineHours must be between 1 and 4320 (180 days)")
	}

	sent := unsafe.OriginSend()
	var totalUgnot int64
	for _, c := range sent {
		if c.Denom == "ugnot" {
			totalUgnot += c.Amount
		}
	}
	if totalUgnot <= 0 {
		panic("must send positive ugnot to fund escrow")
	}

	splits, err := escrowmath.ParseSplitsBps(splitsBpsCSV)
	if err != nil {
		panic(err.Error())
	}
	rawTitles := strings.Split(milestoneTitlesCSV, ",")
	if len(rawTitles) != len(splits) {
		panic("milestone titles count must match splits count")
	}

	amounts, err := escrowmath.ComputeMilestoneAmounts(totalUgnot, splits)
	if err != nil {
		panic(err.Error())
	}

	reviewers := parseUniqueReviewers(reviewersCSV)
	if err := escrowmath.ValidateQuorum(quorum, len(reviewers)); err != nil {
		panic(err.Error())
	}

	milestones := make([]*Milestone, len(splits))
	for i := range splits {
		mt := strings.TrimSpace(rawTitles[i])
		if mt == "" {
			panic("milestone title cannot be empty")
		}
		milestones[i] = &Milestone{
			Index:       i,
			Title:       mt,
			SplitBps:    splits[i],
			AmountUgnot: amounts[i],
			Status:      MilestonePending,
		}
	}

	now := time.Now()
	id := nextPactID
	nextPactID++

	pact := &Pact{
		ID:         id,
		Title:      title,
		Summary:    summary,
		Sponsor:    cur.Previous().Address(),
		Reviewers:  reviewers,
		Quorum:     quorum,
		TotalUgnot: totalUgnot,
		Status:     StatusOpen,
		Milestones: milestones,
		CreatedAt:  now,
		Deadline:   now.Add(time.Duration(deadlineHours) * time.Hour),
	}

	pacts.Set(padID(id), pact)
	totalEscrowedUgnot += totalUgnot
	activeLockedUgnot += totalUgnot
	return id
}

// ClaimPact allows a builder (other than the sponsor) to claim an open pact.
func ClaimPact(cur realm, pactID int64) {
	pact := mustGetPact(pactID)
	if pact.Status != StatusOpen {
		panic("pact is not open")
	}
	if time.Now().After(pact.Deadline) {
		panic("pact deadline has passed")
	}

	caller := cur.Previous().Address()
	if caller == pact.Sponsor {
		panic("sponsor cannot claim own pact")
	}

	pact.Builder = caller
	pact.Status = StatusActive
	getOrCreateBuilder(caller)
}

// SubmitMilestone lets the assigned builder attach verifiable proof (commit/URL/hash) for a milestone.
func SubmitMilestone(cur realm, pactID int64, milestoneIdx int, proofURI string) {
	pact := mustGetPact(pactID)
	if pact.Status != StatusActive {
		panic("pact is not active")
	}
	if cur.Previous().Address() != pact.Builder {
		panic("only assigned builder can submit milestone proof")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(pact.Milestones) {
		panic("invalid milestone index")
	}
	proofURI = strings.TrimSpace(proofURI)
	if proofURI == "" || len(proofURI) > 256 {
		panic("proofURI must be 1..256 characters")
	}

	ms := pact.Milestones[milestoneIdx]
	if ms.Status != MilestonePending {
		panic("milestone already submitted or paid")
	}

	ms.Status = MilestoneSubmitted
	ms.ProofURI = proofURI
	ms.SubmittedAt = time.Now()
}

// ApproveMilestone casts a reviewer vote for a submitted milestone.
// The instant M-of-N quorum is reached, native ugnot is atomically sent to the builder
// via chain/banker and the builder's permanent Proof-of-Contribution XP is updated.
func ApproveMilestone(cur realm, pactID int64, milestoneIdx int) {
	pact := mustGetPact(pactID)
	if pact.Status != StatusActive {
		panic("pact is not active")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(pact.Milestones) {
		panic("invalid milestone index")
	}

	reviewer := cur.Previous().Address()
	if !hasAddress(pact.Reviewers, reviewer) {
		panic("caller is not a designated reviewer")
	}

	ms := pact.Milestones[milestoneIdx]
	if ms.Status != MilestoneSubmitted {
		panic("milestone is not awaiting review")
	}
	if hasAddress(ms.Approvals, reviewer) {
		panic("reviewer already approved this milestone")
	}

	ms.Approvals = append(ms.Approvals, reviewer)
	if len(ms.Approvals) < pact.Quorum {
		return
	}

	// Quorum reached -> settle milestone atomically (checks-effects-interactions)
	now := time.Now()
	ms.Status = MilestonePaid
	ms.PaidAt = now
	pact.ReleasedUgnot += ms.AmountUgnot
	activeLockedUgnot -= ms.AmountUgnot
	totalReleasedUgnot += ms.AmountUgnot

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), pact.Builder, chain.NewCoins(chain.NewCoin("ugnot", ms.AmountUgnot)))

	prof := getOrCreateBuilder(pact.Builder)
	onTime := !now.After(pact.Deadline)
	prof.MilestonesCompleted++
	prof.TotalEarnedUgnot += ms.AmountUgnot
	prof.XP += escrowmath.CalculatePoCXP(ms.AmountUgnot, onTime, !pact.HadDispute)

	allPaid := true
	for _, m := range pact.Milestones {
		if m.Status != MilestonePaid {
			allPaid = false
			break
		}
	}
	if allPaid {
		pact.Status = StatusCompleted
		completedPactsCount++
		prof.PactsCompleted++
	}
}

// RaiseDispute freezes an active pact so the reviewer quorum can arbitrate remaining escrow.
func RaiseDispute(cur realm, pactID int64, reason string) {
	pact := mustGetPact(pactID)
	if pact.Status != StatusActive {
		panic("only active pacts can be disputed")
	}
	caller := cur.Previous().Address()
	if caller != pact.Sponsor && caller != pact.Builder {
		panic("only sponsor or builder can raise a dispute")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > 300 {
		panic("dispute reason must be 1..300 characters")
	}

	pact.Status = StatusDisputed
	pact.DisputeReason = reason
	pact.HadDispute = true
	disputedPactsCount++

	prof := getOrCreateBuilder(pact.Builder)
	prof.DisputesCount++
}

// VoteDisputeResolution lets designated reviewers settle a disputed pact without any central admin.
// Once M-of-N reviewers vote for the same builderShareBps (0..10000), remaining ugnot is
// atomically distributed between builder and sponsor.
func VoteDisputeResolution(cur realm, pactID int64, builderShareBps int64) {
	pact := mustGetPact(pactID)
	if pact.Status != StatusDisputed {
		panic("pact is not in dispute")
	}
	if builderShareBps < 0 || builderShareBps > escrowmath.BpsDenominator {
		panic("builderShareBps must be 0..10000")
	}

	reviewer := cur.Previous().Address()
	if !hasAddress(pact.Reviewers, reviewer) {
		panic("caller is not a designated reviewer")
	}
	for _, v := range pact.DisputeVotes {
		if v.Reviewer == reviewer {
			panic("reviewer already voted on dispute")
		}
	}

	pact.DisputeVotes = append(pact.DisputeVotes, DisputeVote{
		Reviewer:        reviewer,
		BuilderShareBps: builderShareBps,
	})

	matches := 0
	for _, v := range pact.DisputeVotes {
		if v.BuilderShareBps == builderShareBps {
			matches++
		}
	}
	if matches < pact.Quorum {
		return
	}

	remaining := pact.TotalUgnot - pact.ReleasedUgnot
	builderAmt, sponsorAmt, err := escrowmath.ComputeDisputeSplit(remaining, builderShareBps)
	if err != nil {
		panic(err.Error())
	}

	pact.Status = StatusResolved
	pact.ReleasedUgnot += builderAmt
	activeLockedUgnot -= remaining
	totalReleasedUgnot += builderAmt

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if builderAmt > 0 {
		b.SendCoins(cur.Address(), pact.Builder, chain.NewCoins(chain.NewCoin("ugnot", builderAmt)))
		prof := getOrCreateBuilder(pact.Builder)
		prof.TotalEarnedUgnot += builderAmt
	}
	if sponsorAmt > 0 {
		b.SendCoins(cur.Address(), pact.Sponsor, chain.NewCoins(chain.NewCoin("ugnot", sponsorAmt)))
	}
}

// ReclaimExpired allows the sponsor to safely reclaim any unpaid ugnot after the deadline.
func ReclaimExpired(cur realm, pactID int64) {
	pact := mustGetPact(pactID)
	if cur.Previous().Address() != pact.Sponsor {
		panic("only sponsor can reclaim expired escrow")
	}
	if pact.Status != StatusOpen && pact.Status != StatusActive {
		panic("pact cannot be reclaimed in current state")
	}
	if !time.Now().After(pact.Deadline) {
		panic("pact deadline has not passed yet")
	}

	remaining := pact.TotalUgnot - pact.ReleasedUgnot
	pact.Status = StatusExpired
	activeLockedUgnot -= remaining

	if remaining > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(cur.Address(), pact.Sponsor, chain.NewCoins(chain.NewCoin("ugnot", remaining)))
	}
}

// GetPactCount returns total number of created pacts.
func GetPactCount() int64 {
	return nextPactID - 1
}

// GetBuilderXP returns a builder's on-chain Proof-of-Contribution XP.
func GetBuilderXP(addr address) int64 {
	v := builders.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(*BuilderProfile).XP
}

func mustGetPact(id int64) *Pact {
	v := pacts.Get(padID(id))
	if v == nil {
		panic("pact not found")
	}
	return v.(*Pact)
}

func getOrCreateBuilder(addr address) *BuilderProfile {
	key := addr.String()
	if v := builders.Get(key); v != nil {
		return v.(*BuilderProfile)
	}
	p := &BuilderProfile{Address: addr}
	builders.Set(key, p)
	return p
}

func parseUniqueReviewers(csv string) []address {
	parts := strings.Split(strings.TrimSpace(csv), ",")
	out := make([]address, 0, len(parts))
	for _, raw := range parts {
		s := strings.TrimSpace(raw)
		if s == "" {
			continue
		}
		a := address(s)
		if !a.IsValid() {
			panic("invalid reviewer address: " + s)
		}
		if !hasAddress(out, a) {
			out = append(out, a)
		}
	}
	return out
}

package oathledger

import (
	"strconv"
	"strings"

	"gno.land/p/g1ty0rp975ndkcse760v0zt659f4phs4z8lueud7/escrowmath"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Render serves deterministic, sanitized, multi-route Markdown for gnoweb:
//   - ""               : Dashboard overview, live telemetry & active pacts table
//   - "pact/<id>"      : Detailed pact view with milestone progress & one-click txlinks
//   - "builder/<addr>" : Immutable Proof-of-Contribution builder resume
//   - "leaderboard"    : Top verified builders ranked by on-chain PoC XP
func Render(path string) string {
	path = strings.Trim(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	if path == "leaderboard" {
		return renderLeaderboard()
	}
	if strings.HasPrefix(path, "pact/") {
		idStr := strings.TrimPrefix(path, "pact/")
		id, err := strconv.ParseInt(idStr, 10, 64)
		if err != nil {
			return md.H1("Invalid Pact ID") + "Use `/pact/<id>`."
		}
		return renderPactDetail(id)
	}
	if strings.HasPrefix(path, "builder/") {
		addrStr := strings.TrimPrefix(path, "builder/")
		return renderBuilderProfile(addrStr)
	}
	return md.H1("Route Not Found") + "Supported routes: `/`, `/pact/<id>`, `/builder/<addr>`, `/leaderboard`."
}

func renderHome() string {
	var b strings.Builder
	b.WriteString(md.H1("OathLedger — Trustless Milestone Escrow & PoC Board"))
	b.WriteString("> Native Gno.land multi-milestone `ugnot` escrow with M-of-N peer-reviewer quorums, trustless dispute arbitration, and immutable Proof-of-Contribution builder reputation.\n\n")

	b.WriteString(md.H2("Protocol Telemetry"))
	b.WriteString(ufmt.Sprintf("- **Total Pacts**: %d (%d completed, %d disputed)\n", nextPactID-1, completedPactsCount, disputedPactsCount))
	b.WriteString(ufmt.Sprintf("- **Active Escrow Locked**: `%s` (`%d ugnot`)\n", escrowmath.FormatGnot(activeLockedUgnot), activeLockedUgnot))
	b.WriteString(ufmt.Sprintf("- **Total Released to Builders**: `%s`\n", escrowmath.FormatGnot(totalReleasedUgnot)))
	b.WriteString(ufmt.Sprintf("- **Verified Builders**: %d — %s\n\n", builders.Size(), md.Link("View PoC Leaderboard", ":leaderboard")))

	b.WriteString(md.H2("Escrow Pacts"))
	if pacts.Size() == 0 {
		b.WriteString("_No pacts created yet. Use `CreatePact` with `-send <amount>ugnot` to lock your first milestone bounty._\n")
		return b.String()
	}

	b.WriteString("| ID | Title | Progress | Escrow | Quorum | Status |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	pacts.ReverseIterate("", "", func(_ string, val any) bool {
		p := val.(*Pact)
		idStr := strconv.FormatInt(p.ID, 10)
		link := md.Link("#"+idStr+" "+p.Title, ":pact/"+idStr)
		bar := escrowmath.ProgressBar(p.ReleasedUgnot, p.TotalUgnot, 8)
		b.WriteString(ufmt.Sprintf("| #%s | %s | `%s` | `%s` | %d/%d | **%s** |\n",
			idStr,
			link,
			bar,
			escrowmath.FormatGnot(p.TotalUgnot),
			p.Quorum,
			len(p.Reviewers),
			string(p.Status),
		))
		return false
	})

	b.WriteString("\n" + md.H3("Quick Navigation"))
	b.WriteString("- " + md.Link("Proof-of-Contribution Leaderboard", ":leaderboard") + "\n")
	return b.String()
}

func renderPactDetail(id int64) string {
	v := pacts.Get(padID(id))
	if v == nil {
		return md.H1("Pact Not Found") + md.Link("Back to OathLedger", ":")
	}
	p := v.(*Pact)
	idStr := strconv.FormatInt(p.ID, 10)

	var b strings.Builder
	b.WriteString(md.H1(ufmt.Sprintf("Pact #%d — %s", p.ID, sanitize.InlineText(p.Title))))
	b.WriteString(sanitize.InlineText(p.Summary) + "\n\n")

	b.WriteString(ufmt.Sprintf("- **Status**: `%s`\n", string(p.Status)))
	b.WriteString(ufmt.Sprintf("- **Progress**: `%s` (`%s` / `%s`)\n",
		escrowmath.ProgressBar(p.ReleasedUgnot, p.TotalUgnot, 12),
		escrowmath.FormatGnot(p.ReleasedUgnot),
		escrowmath.FormatGnot(p.TotalUgnot),
	))
	b.WriteString(ufmt.Sprintf("- **Sponsor**: `%s`\n", p.Sponsor.String()))
	if p.Builder != "" {
		b.WriteString(ufmt.Sprintf("- **Builder**: %s\n", md.Link(p.Builder.String(), ":builder/"+p.Builder.String())))
	} else {
		claimURL := txlink.NewLink("ClaimPact").AddArgs("pactID", idStr).URL()
		b.WriteString(ufmt.Sprintf("- **Builder**: _Unclaimed_ — %s\n", md.Link("Claim This Pact", claimURL)))
	}
	b.WriteString(ufmt.Sprintf("- **Reviewer Quorum**: %d of %d reviewers\n", p.Quorum, len(p.Reviewers)))
	b.WriteString(ufmt.Sprintf("- **Deadline**: `%s`\n\n", p.Deadline.UTC().Format("2006-01-02 15:04 UTC")))

	b.WriteString(md.H2("Milestones"))
	b.WriteString("| # | Milestone | Split | Payout | Status | Approvals | Proof / Action |\n")
	b.WriteString("|---|---|---|---|---|---|---|\n")
	for _, m := range p.Milestones {
		idxStr := strconv.Itoa(m.Index)
		action := "-"
		switch m.Status {
		case MilestonePending:
			if p.Status == StatusActive {
				subURL := txlink.NewLink("SubmitMilestone").AddArgs("pactID", idStr, "milestoneIdx", idxStr).URL()
				action = md.Link("Submit Proof", subURL)
			}
		case MilestoneSubmitted:
			appURL := txlink.NewLink("ApproveMilestone").AddArgs("pactID", idStr, "milestoneIdx", idxStr).URL()
			action = ufmt.Sprintf("`%s` · %s", sanitize.InlineText(m.ProofURI), md.Link("Approve", appURL))
		case MilestonePaid:
			action = ufmt.Sprintf("`%s` (Paid)", sanitize.InlineText(m.ProofURI))
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %d.%02d%% | `%s` | **%s** | %d/%d | %s |\n",
			m.Index+1,
			sanitize.InlineText(m.Title),
			m.SplitBps/100,
			m.SplitBps%100,
			escrowmath.FormatGnot(m.AmountUgnot),
			string(m.Status),
			len(m.Approvals),
			p.Quorum,
			action,
		))
	}

	if p.Status == StatusDisputed {
		b.WriteString("\n" + md.H2("Active Dispute"))
		b.WriteString(ufmt.Sprintf("- **Reason**: %s\n", sanitize.InlineText(p.DisputeReason)))
		b.WriteString(ufmt.Sprintf("- **Resolution Votes Cast**: %d / %d quorum\n", len(p.DisputeVotes), p.Quorum))
	}

	b.WriteString("\n" + md.Link("← Back to All Pacts", ":"))
	return b.String()
}

func renderBuilderProfile(addrStr string) string {
	v := builders.Get(addrStr)
	if v == nil {
		return md.H1("Builder Not Found") + md.Link("Back to Leaderboard", ":leaderboard")
	}
	prof := v.(*BuilderProfile)

	var b strings.Builder
	b.WriteString(md.H1("Builder Proof-of-Contribution Resume"))
	b.WriteString(ufmt.Sprintf("- **Address**: `%s`\n", prof.Address.String()))
	b.WriteString(ufmt.Sprintf("- **PoC Tier**: **%s** (`%d XP`)\n", escrowmath.TierForXP(prof.XP), prof.XP))
	b.WriteString(ufmt.Sprintf("- **Total Verified Earnings**: `%s`\n", escrowmath.FormatGnot(prof.TotalEarnedUgnot)))
	b.WriteString(ufmt.Sprintf("- **Milestones Paid**: %d | **Pacts Completed**: %d | **Disputes**: %d\n\n",
		prof.MilestonesCompleted, prof.PactsCompleted, prof.DisputesCount))
	b.WriteString(md.Link("← Back to Leaderboard", ":leaderboard"))
	return b.String()
}

func renderLeaderboard() string {
	var b strings.Builder
	b.WriteString(md.H1("OathLedger — Proof-of-Contribution Leaderboard"))
	if builders.Size() == 0 {
		b.WriteString("_No builders ranked yet._\n\n" + md.Link("← Back to OathLedger", ":"))
		return b.String()
	}

	b.WriteString("| Builder | Tier | PoC XP | Milestones | Total Earned |\n")
	b.WriteString("|---|---|---|---|---|\n")
	builders.Iterate("", "", func(key string, val any) bool {
		prof := val.(*BuilderProfile)
		b.WriteString(ufmt.Sprintf("| %s | **%s** | `%d` | %d | `%s` |\n",
			md.Link(key, ":builder/"+key),
			escrowmath.TierForXP(prof.XP),
			prof.XP,
			prof.MilestonesCompleted,
			escrowmath.FormatGnot(prof.TotalEarnedUgnot),
		))
		return false
	})
	b.WriteString("\n" + md.Link("← Back to All Pacts", ":"))
	return b.String()
}

