	idKey := formatIDKey(attestationID)
	att, exists := attestations.Get(idKey).(*Attestation)
	if !exists {
		panic("aegis_attest: attestation ID not found")
	}
	caller := cur.Previous().Address()
	if caller != att.Author {
		panic("aegis_attest: only attestation author may revoke")
	}
	if att.Status == StatusRevoked {
		panic("aegis_attest: attestation already revoked")
	}

	cleanReason := sanitizeCell(reason, MaxSummaryLen)
	if len(cleanReason) == 0 {
		cleanReason = "revoked by author"
	}

	att.Status = StatusRevoked
	att.RevokedHeight = runtime.ChainHeight()
	att.RevokeReason = cleanReason

	if prof, ok := agents.Get(att.Subject.String()).(*AgentProfile); ok {
		if prof.AcceptedCount > 0 {
			prof.AcceptedCount--
		}
		prof.RevokedCount++
	}
	if totalActive > 0 {
		totalActive--
	}
	totalRevoked++

	chain.Emit(
		"AttestationRevoked",
		"id", strconv.FormatUint(att.ID, 10),
		"author", caller.String(),
		"reason", cleanReason,
	)
}

// GetSummary returns zero-gas telemetry summary for QEval monitoring.
func GetSummary() string {
	return ufmt.Sprintf(
		"agents=%d|total_attestations=%d|active=%d|revoked=%d|height=%d",
		totalAgents, nextAttestationID, totalActive, totalRevoked, runtime.ChainHeight(),
	)
}

// GetAgentScoreBps returns the current EMA score (0..10000 bps) for an agent.
func GetAgentScoreBps(subject address) int {
	prof, exists := agents.Get(subject.String()).(*AgentProfile)
	if !exists {
		return -1
	}
	return prof.EmaScoreBps
}

// VerifyEvidenceHash reports true when an active non-revoked attestation matches the triple.
func VerifyEvidenceHash(subject address, taskOrMarketID string, evidenceSHA256 string) bool {
	dedupKey := subject.String() + "|" + sanitizeCell(taskOrMarketID, MaxTaskIDLen) + "|" + normalizeSHA256(evidenceSHA256)
	rawID, exists := dedupIndex.Get(dedupKey).(uint64)
	if !exists {
		return false
	}
	att, ok := attestations.Get(formatIDKey(rawID)).(*Attestation)
	if !ok {
		return false
	}
	return att.Status == StatusVerified
}

// Render serves native gnoweb markdown views for root dashboard and agent/:address.
func Render(path string) string {
	cleanPath := strings.Trim(path, "/")
	if strings.HasPrefix(cleanPath, "agent/") {
		target := strings.TrimPrefix(cleanPath, "agent/")
		return renderAgentDetail(target)
	}
	return renderHome()
}

func renderHome() string {
	regURL := txlink.NewLink("RegisterAgent").
		AddArgs("handle", "my-agent", "capabilities", "evidence-verification,onchain-eval").
		URL()

	var b strings.Builder
	b.WriteString("# Aegis Attest: Verifiable Agent Reputation & Evidence Ledger\n\n")
	b.WriteString("On-chain SHA-256 evidence anchoring, author-gated revocation, and bounded EMA scoring in Gno.\n\n")
	b.WriteString(ufmt.Sprintf("Live Block: `#%d` | [Register Agent](%s)\n\n", runtime.ChainHeight(), regURL))

	b.WriteString("## Ledger Metrics\n\n")
	b.WriteString("| Metric | Value |\n")
	b.WriteString("| --- | --- |\n")
	b.WriteString(ufmt.Sprintf("| Registered Agents | %d |\n", totalAgents))
	b.WriteString(ufmt.Sprintf("| Total Attestations | %d (%d active, %d revoked) |\n\n", nextAttestationID, totalActive, totalRevoked))

	b.WriteString("## Registered Agents\n\n")
	if agents.Size() == 0 {
		b.WriteString("_No agents registered yet._\n\n")
	} else {
		b.WriteString("| Handle | Address | Capabilities | EMA Score (bps) | Active / Total |\n")
		b.WriteString("| --- | --- | --- | --- | --- |\n")
		agents.Iterate("", "", func(_ string, v any) bool {
			p := v.(*AgentProfile)
			b.WriteString(ufmt.Sprintf(
				"| %s | [%s](%s:agent/%s) | %s | `%d` | %d / %d |\n",
				p.Handle, shortAddr(p.Addr), realmURLPath, p.Addr.String(), p.Capabilities, p.EmaScoreBps, p.AcceptedCount, p.AttestationCount,
			))
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## Recent Attestations\n\n")
	if attestations.Size() == 0 {
		b.WriteString("_No attestations anchored yet._\n")
		return b.String()
	}

	b.WriteString("| ID | Task / Market | Subject | Score (bps) | Evidence SHA-256 | Status |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	count := 0
	attestations.ReverseIterate("", "", func(_ string, v any) bool {
		a := v.(*Attestation)
		b.WriteString(ufmt.Sprintf(
			"| #%d | %s | [%s](%s:agent/%s) | `%d` | `%s...` | **%s** |\n",
			a.ID, a.TaskOrMarketID, shortAddr(a.Subject), realmURLPath, a.Subject.String(), a.ScoreBps, a.EvidenceSHA256[:12], a.Status,
		))
		count++
		return count >= 25
	})
	return b.String()
}

func renderAgentDetail(addrStr string) string {
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Agent Audit: `%s`\n\n[<- Back to Aegis Attest](%s)\n\n", addrStr, realmURLPath))
	p, exists := agents.Get(addrStr).(*AgentProfile)
	if !exists {
		return b.String() + "_Agent not found in ledger._\n"
	}
	b.WriteString(ufmt.Sprintf(
		"- **Handle**: %s\n- **Capabilities**: %s\n- **EMA Score**: `%d` bps\n- **Active / Revoked**: %d / %d\n\n",
		p.Handle, p.Capabilities, p.EmaScoreBps, p.AcceptedCount, p.RevokedCount,
	))
	b.WriteString("## Agent Attestations\n\n")
	b.WriteString("| ID | Task / Market | Score | SHA-256 | Summary | Status |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	prefix := addrStr + ":"
	bySubject.ReverseIterate(prefix, prefix+"~", func(_ string, v any) bool {
		id := v.(uint64)
		if a, ok := attestations.Get(formatIDKey(id)).(*Attestation); ok {
			b.WriteString(ufmt.Sprintf(
				"| #%d | %s | `%d` | `%s` | %s | **%s** |\n",
				a.ID, a.TaskOrMarketID, a.ScoreBps, a.EvidenceSHA256, a.Summary, a.Status,
			))
		}
		return false
	})
	return b.String()
}

func ensureProfile(addr address) *AgentProfile {
	if prof, exists := agents.Get(addr.String()).(*AgentProfile); exists {
		return prof
	}
	prof := &AgentProfile{
		Addr:             addr,
		Handle:           "agent-" + shortAddr(addr),
		Capabilities:     "external-subject",
		RegisteredHeight: runtime.ChainHeight(),
	}
	agents.Set(addr.String(), prof)
	totalAgents++
	return prof
}

func normalizeSHA256(s string) string {
	trimmed := strings.ToLower(strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(s, "0x"), "0X")))
	if len(trimmed) != 64 {
		panic("aegis_attest: evidenceSHA256 must be 64 hex chars")
	}
	for i := 0; i < len(trimmed); i++ {
		c := trimmed[i]
		isDigit := c >= '0' && c <= '9'
		isHex := c >= 'a' && c <= 'f'
		if !isDigit && !isHex {
			panic("aegis_attest: invalid hex char in evidenceSHA256")
		}
	}
	return trimmed
}

func sanitizeCell(s string, maxLen int) string {
	clean := strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(strings.ReplaceAll(s, "\r", " "), "\n", " "), "|", "/"))
	if len(clean) > maxLen {
		return clean[:maxLen]
	}
	return clean
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-4:]
}

func formatIDKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	if len(s) >= 12 {
		return s
	}
	return strings.Repeat("0", 12-len(s)) + s
}

// Package taverntab is the TavernTab realm: a tavern tab (escrow) for the
// Gnome Tavern. At the tavern you don't pay per drink — you open a tab.
// The realm holds your GNOT, and the tab is later settled (the payee gets
// paid) or cancelled (you get refunded), always by the payer, always on
// the record.
//
// Flow:
//
//	id := OpenTab(payee, "two ales and a stew") // -send 5000000ugnot
//	SettleTab(id) // payer only: realm pays the payee
//	// or
//	CancelTab(id) // payer only: realm refunds the payer in full
//
// Render("") draws the public board on gnoweb: every tab, its status,
// and how much the tavern is holding right now, so anyone can verify
// the state in a browser without a wallet.
package taverntab

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// tabStatus is the lifecycle state of a tab.
type tabStatus uint8

const (
	statusOpen tabStatus = iota
	statusSettled
	statusCancelled
)

func (s tabStatus) String() string {
	switch s {
	case statusOpen:
		return "open"
	case statusSettled:
		return "settled"
	case statusCancelled:
		return "cancelled"
	}
	return "unknown"
}

// tab is a single escrow record. The coins themselves sit in the realm's
// bank account; the tab records who they belong to and where they may go.
type tab struct {
	id     uint64
	payer  address
	payee  address
	amount int64 // ugnot held for this tab
	memo   string
	status tabStatus
}

var (
	tabs      = map[uint64]*tab{}
	nextID    uint64 = 1
	heldTotal int64 // ugnot currently held across all open tabs
)

// OpenTab opens a tab: the caller deposits GNOT (sent with the call),
// recorded against a payee. Only a direct user call is accepted, so the
// origin-send envelope really is the caller's deposit. Returns the tab id.
func OpenTab(cur realm, payee address, memo string) uint64 {
	if !cur.Previous().IsUserCall() {
		panic("OpenTab: only direct user calls can open a tab")
	}
	payer := cur.Previous().Address()
	if payee == payer {
		panic("OpenTab: payee must differ from payer")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount <= 0 {
		panic("OpenTab: send a single positive ugnot amount with the call")
	}

	id := nextID
	nextID++
	tabs[id] = &tab{
		id:     id,
		payer:  payer,
		payee:  payee,
		amount: sent[0].Amount,
		memo:   memo,
		status: statusOpen,
	}
	heldTotal += sent[0].Amount
	return id
}

// SettleTab settles an open tab: the held amount goes to the payee.
// Only the tab's payer can settle, and only once.
func SettleTab(cur realm, id uint64) {
	t := mustTab(id)
	if cur.Previous().Address() != t.payer {
		panic("SettleTab: only the payer can settle this tab")
	}
	if t.status != statusOpen {
		panic("SettleTab: tab is not open")
	}
	t.status = statusSettled
	heldTotal -= t.amount
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), t.payee, chain.Coins{{Denom: "ugnot", Amount: t.amount}})
}

// CancelTab cancels an open tab: the held amount is refunded in full to
// the payer. Only the tab's payer can cancel, and only once.
func CancelTab(cur realm, id uint64) {
	t := mustTab(id)
	if cur.Previous().Address() != t.payer {
		panic("CancelTab: only the payer can cancel this tab")
	}
	if t.status != statusOpen {
		panic("CancelTab: tab is not open")
	}
	t.status = statusCancelled
	heldTotal -= t.amount
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), t.payer, chain.Coins{{Denom: "ugnot", Amount: t.amount}})
}

// GetTab returns a read-only snapshot of one tab.
func GetTab(id uint64) (payer, payee address, amount int64, memo, status string, found bool) {
	t, ok := tabs[id]
	if !ok {
		return "", "", 0, "", "", false
	}
	return t.payer, t.payee, t.amount, t.memo, t.status.String(), true
}

// HeldTotal returns the ugnot the tavern is currently holding.
func HeldTotal() int64 {
	return heldTotal
}

// Render draws the public board. Render("") lists every tab grouped by
// status plus the held total; Render("<id>") shows a single tab.
func Render(path string) string {
	if path != "" {
		id, err := strconv.ParseUint(path, 10, 64)
		if err != nil {
			return "404: unknown tab"
		}
		t, ok := tabs[id]
		if !ok {
			return "404: unknown tab"
		}
		return renderTab(t)
	}

	out := "# TavernTab — the Gnome Tavern tab board\n\n"
	out += ufmt.Sprintf("The tavern is holding **%dugnot** across open tabs.\n\n", heldTotal)
	for _, s := range []tabStatus{statusOpen, statusSettled, statusCancelled} {
		out += ufmt.Sprintf("## %s tabs\n\n", title(s.String()))
		found := false
		for id := uint64(1); id < nextID; id++ {
			t := tabs[id]
			if t.status != s {
				continue
			}
			found = true
			out += ufmt.Sprintf("- [tab %d](%s): %s owes %s %dugnot — %s\n",
				t.id, strconv.FormatUint(t.id, 10), t.payer, t.payee, t.amount, sanitize.InlineText(t.memo))
		}
		if !found {
			out += "- none\n"
		}
		out += "\n"
	}
	return out
}

func renderTab(t *tab) string {
	return ufmt.Sprintf("# Tab %d\n\n- payer: %s\n- payee: %s\n- amount: %dugnot\n- memo: %s\n- status: %s\n",
		t.id, t.payer, t.payee, t.amount, sanitize.InlineText(t.memo), t.status.String())
}

func mustTab(id uint64) *tab {
	t, ok := tabs[id]
	if !ok {
		panic("unknown tab ID")
	}
	return t
}

func title(s string) string {
	if s == "" {
		return s
	}
	return string(s[0]-'a'+'A') + s[1:]
}

package taverntab

import (
	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var realmAddr = chain.PackageAddress("gno.land/r/g1u70h54xphw9qgkzzwn6jujeegxqtdfqvzc9dec/taverntab")

func balanceOf(addr address) int64 {
	b := banker.NewReadonlyBanker()
	return b.GetCoin(addr, "ugnot")
}

func resetTestState() {
	tabs = map[uint64]*tab{}
	nextID = 1
	heldTotal = 0
}

// openTabAs drives OpenTab the way a real user call would: the given
// user becomes the previous realm, and amount ugnot rides the call.
// The test VM tracks the origin-send envelope but does not move coins
// into the realm account, so the realm is issued the deposit to fund
// the later payout (same pattern as the atomicswap example tests).
func openTabAs(cur realm, payer, payee address, amount int64, memo string) uint64 {
	testing.SetRealm(testing.NewUserRealm(payer))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: amount}})
	testing.IssueCoins(realmAddr, chain.Coins{{Denom: "ugnot", Amount: amount}})
	return OpenTab(cross(cur), payee, memo)
}

func TestOpenAndSettlePaysPayee(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")

	id := openTabAs(cur, payer, payee, 5000, "two ales and a stew")
	uassert.Equal(t, uint64(1), id)
	uassert.Equal(t, int64(5000), HeldTotal())
	uassert.Equal(t, int64(0), balanceOf(payee))

	_, tabPayee, amount, _, status, found := GetTab(id)
	uassert.True(t, found)
	uassert.Equal(t, payee, tabPayee)
	uassert.Equal(t, int64(5000), amount)
	uassert.Equal(t, "open", status)

	testing.SetRealm(testing.NewUserRealm(payer))
	SettleTab(cross(cur), id)

	uassert.Equal(t, int64(5000), balanceOf(payee), "payee must receive the held amount")
	uassert.Equal(t, int64(0), HeldTotal())
	_, _, _, _, status, _ = GetTab(id)
	uassert.Equal(t, "settled", status)
}

func TestOpenAndCancelRefundsPayer(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")

	id := openTabAs(cur, payer, payee, 7000, "a round for the table")
	uassert.Equal(t, int64(0), balanceOf(payer))

	testing.SetRealm(testing.NewUserRealm(payer))
	CancelTab(cross(cur), id)

	uassert.Equal(t, int64(7000), balanceOf(payer), "payer must be refunded in full")
	uassert.Equal(t, int64(0), balanceOf(payee))
	uassert.Equal(t, int64(0), HeldTotal())
	_, _, _, _, status, _ := GetTab(id)
	uassert.Equal(t, "cancelled", status)
}

func TestNonPayerCannotSettleOrCancel(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")
	stranger := testutils.TestAddress("stranger")

	id := openTabAs(cur, payer, payee, 3000, "stranger keep out")

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.AbortsWithMessage(t, cur, "SettleTab: only the payer can settle this tab",
		func() { SettleTab(cross(cur), id) })
	uassert.AbortsWithMessage(t, cur, "CancelTab: only the payer can cancel this tab",
		func() { CancelTab(cross(cur), id) })

	// The payee is not the payer either: settling is not theirs to trigger.
	testing.SetRealm(testing.NewUserRealm(payee))
	uassert.AbortsWithMessage(t, cur, "SettleTab: only the payer can settle this tab",
		func() { SettleTab(cross(cur), id) })

	// Tab untouched: still open, tavern still holding the coins.
	_, _, _, _, status, _ := GetTab(id)
	uassert.Equal(t, "open", status)
	uassert.Equal(t, int64(3000), HeldTotal())
}

func TestDoubleSettleRejected(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")

	id := openTabAs(cur, payer, payee, 4000, "settle me once")

	testing.SetRealm(testing.NewUserRealm(payer))
	SettleTab(cross(cur), id)
	uassert.Equal(t, int64(4000), balanceOf(payee))

	uassert.AbortsWithMessage(t, cur, "SettleTab: tab is not open",
		func() { SettleTab(cross(cur), id) })
	uassert.AbortsWithMessage(t, cur, "CancelTab: tab is not open",
		func() { CancelTab(cross(cur), id) })
	uassert.Equal(t, int64(4000), balanceOf(payee), "payee must not be paid twice")
}

func TestSettleAfterCancelRejected(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")

	id := openTabAs(cur, payer, payee, 4000, "cancel me once")

	testing.SetRealm(testing.NewUserRealm(payer))
	CancelTab(cross(cur), id)
	uassert.AbortsWithMessage(t, cur, "SettleTab: tab is not open",
		func() { SettleTab(cross(cur), id) })
	uassert.Equal(t, int64(0), balanceOf(payee))
}

func TestRenderBoard(cur realm, t *testing.T) {
	defer resetTestState()
	payer := testutils.TestAddress("payer")
	payee := testutils.TestAddress("payee")

	id := openTabAs(cur, payer, payee, 2500, "board special")
	board := Render("")
	uassert.True(t, contains(board, "TavernTab"), "board must carry the title")
	uassert.True(t, contains(board, "2500ugnot"), "board must show the held amount")

	one := Render("1")
	uassert.True(t, contains(one, "open"), "single-tab view must show the status")
	uassert.Equal(t, uint64(1), id)
	uassert.Equal(t, "404: unknown tab", Render("999"))
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}
